-- noiseMaker.lua
-- ===========================================================================

NoiseMaker = {}
NoiseMaker.__index = NoiseMaker

local function log(message, logCoalition, duration)
    duration = duration or 10
    trigger.action.outTextForCoalition(logCoalition, message, duration, false)
    env.info(message, false)
end

local function debugMessage(message, duration)
    if trigger.misc.getUserFlag("Debug") == 1 then
        duration = duration or 10
        trigger.action.outText(message, duration, false)
        env.info(message, false)
    end
end

-- Constructor
-- name: Identifier (e.g. "Kursk-Decoy-1")
-- x, z: DCS world coordinates at deploy (submarine position)
-- depth: Depth at deploy (submarine depth)
-- activationDelay: Seconds before noise maker activates (60, 120, 180, 240)
-- ownerCoalition: coalition of the submarine that deployed it
-- thermalLayerDepth: thermal layer depth (for buoy detection compatibility)
function NoiseMaker:new(name, x, z, depth, activationDelay, ownerCoalition, thermalLayerDepth)
    local driftHeading = math.random() * 360
    local obj = {
        name = name,
        -- Position at deployment (captured immediately)
        deployX = x,
        deployZ = z,
        deployDepth = depth,
        -- Current position (may drift after activation)
        x = x,
        z = z,
        depth = depth,
        -- Duck-type fields for buoy detection compatibility
        speed = 3,                  -- slow drift speed in m/s (~6 kts)
        noiseFactor = 2.0,          -- loud to attract attention
        -- Internal fields
        driftHeading = driftHeading,
        activationDelay = activationDelay or 60,
        batteryLife = 600,          -- 10 minutes active time
        ownerCoalition = ownerCoalition or coalition.side.RED,
        thermalLayerDepth = thermalLayerDepth or 90,
        active = false,             -- not active until delay passes
        deployed = true,            -- deployed but may not be active yet
        elapsedTime = 0,
        activeTime = 0,
        lastUpdateTime = timer.getTime(),
        marker = nil,
        updateScheduleId = nil
    }
    setmetatable(obj, NoiseMaker)
    obj:startUpdateLoop()
    log(name .. " deployed! Activates in " .. activationDelay .. "s", ownerCoalition)
    return obj
end

-- Duck-type compatibility: buoys call sub:isAlive()
function NoiseMaker:isAlive()
    return self.active
end

function NoiseMaker:isDeployed()
    return self.deployed
end

-- Main update loop: runs every second
function NoiseMaker:startUpdateLoop()
    local function update()
        if not self.deployed then return end

        local currentTime = timer.getTime()
        local dt = currentTime - self.lastUpdateTime
        self.lastUpdateTime = currentTime
        self.elapsedTime = self.elapsedTime + dt

        -- Check activation
        if not self.active then
            if self.elapsedTime >= self.activationDelay then
                self.active = true
                log(self.name .. " ACTIVATED! Emitting noise.", self.ownerCoalition)
                -- Activation sound (sub coalition only)
                if ASW_SOUND then
                    ASW_SOUND:playForCoalition(self.ownerCoalition, "noisemaker_loop")
                end
            end
        else
            -- Active: count active time and check battery
            self.activeTime = self.activeTime + dt
            if self.activeTime >= self.batteryLife then
                self:expire()
                return
            end

            -- Drift in random direction
            self:drift(dt)
        end

        -- Update marker for sub coalition
        self:updateMarker()

        self.updateScheduleId = timer.scheduleFunction(function()
            update()
        end, nil, timer.getTime() + 1)
    end

    update()
end

-- Drift slowly in the random heading
function NoiseMaker:drift(dt)
    local headingRad = math.rad(self.driftHeading)
    local distance = self.speed * dt
    self.x = self.x + distance * math.cos(headingRad)
    self.z = self.z + distance * math.sin(headingRad)
end

-- Battery expired
function NoiseMaker:expire()
    self.active = false
    self.deployed = false
    self:stopUpdateLoop()
    self:clearMarker()
    log(self.name .. " battery depleted. Noise maker silent.", self.ownerCoalition)
end

-- Remove noise maker
function NoiseMaker:remove()
    self.active = false
    self.deployed = false
    self:stopUpdateLoop()
    self:clearMarker()
end

function NoiseMaker:stopUpdateLoop()
    if self.updateScheduleId then
        timer.removeFunction(self.updateScheduleId)
        self.updateScheduleId = nil
    end
end

-- Update F10 map marker (visible to sub coalition only)
function NoiseMaker:updateMarker()
    local coord
    local status

    if not self.active then
        -- While in standby use the captured deployment coordinates/depth
        coord = COORDINATE:New(self.deployX, 0, self.deployZ)
        local remaining = self.activationDelay - self.elapsedTime
        status = string.format("STANDBY (%.0fs)", math.max(0, remaining))
    else
        -- Once active use the decoy's current (possibly drifting) position
        coord = COORDINATE:New(self.x, 0, self.z)
        local remaining = self.batteryLife - self.activeTime
        status = string.format("ACTIVE (%.0fs)", math.max(0, remaining))
    end

    local depthToShow = self.deployDepth or self.depth
    local text = string.format("%s | DECOY | %s | Depth: %.0fm",
        self.name, status, depthToShow)

    if self.marker then
        self.marker:UpdateCoordinate(coord)
        self.marker:UpdateText(text)
    else
        self.marker = MARKER:New(coord, text):ReadOnly():ToCoalition(self.ownerCoalition)
    end
end

-- Remove map marker
function NoiseMaker:clearMarker()
    if self.marker then
        self.marker:Remove()
        self.marker = nil
    end
end

-- ===========================================================================
-- anti_submarine_torpedo.lua
-- ===========================================================================

AntiSubmarineTorpedo = {}
AntiSubmarineTorpedo.__index = AntiSubmarineTorpedo

local function log(message, logCoalition, duration)
    duration = duration or 10
    trigger.action.outTextForCoalition(logCoalition, message, duration, false)
    env.info(message, false)
end

local function logAll(message, duration)
    duration = duration or 10
    trigger.action.outText(message, duration, false)
    env.info(message, false)
end

local function debugMessage(message, duration)
    if trigger.misc.getUserFlag("Debug") == 1 then
        duration = duration or 10
        trigger.action.outText(message, duration, false)
        env.info(message, false)
    end
end

if not _torpedoMarkIdCounter then _torpedoMarkIdCounter = 100000 end
local function nextMarkId()
    _torpedoMarkIdCounter = _torpedoMarkIdCounter + 1
    return _torpedoMarkIdCounter
end

-- Constructor
-- name: Identifier (e.g. "Hunter1-Torpedo-1")
-- x, z: DCS world coordinates at launch
-- heading: Initial heading in degrees (player's heading)
-- searchDepth: Depth to run at in meters (0, 50, 100, 150, 200, 250, 300, 400, 500)
-- ownerCoalition: coalition side
-- submarines: table of VirtualSubmarine instances to hunt
-- thermalLayerDepth: thermal layer depth for detection (default 90)
function AntiSubmarineTorpedo:new(name, x, z, heading, searchDepth, ownerCoalition, submarines, thermalLayerDepth)
    local obj = {
        name = name,
        x = x,
        z = z,
        heading = heading,
        depth = 0,
        targetDepth = searchDepth or 100,
        depthRate = 20,              -- meters per second depth change
        speed = 15.43,               -- 30 knots in m/s
        turnRate = 3,                -- degrees per second
        maxDetectionRange = 1500,    -- 1.5 km sonar range
        thermalLayerDepth = thermalLayerDepth or 90,
        killRadius = 150,            -- meters
        depthTolerance = 50,         -- meters
        batteryLife = 300,           -- seconds
        ownerCoalition = ownerCoalition or coalition.side.BLUE,
        submarines = submarines or {},
        active = true,
        hasTarget = false,
        lastContactX = nil,
        lastContactZ = nil,
        lastContactDepth = nil,
        elapsedTime = 0,
        lastUpdateTime = timer.getTime(),
        lastMarkerTime = 0,         -- Track when last marker was created
        lastHomingPingTime = 0,      -- Track homing ping interval
        prevMarkerX = x,
        prevMarkerZ = z,
        markerIds = {},
        textMarkerId = nil,
        updateScheduleId = nil
    }
    setmetatable(obj, AntiSubmarineTorpedo)
    obj:startUpdateLoop()
    obj:markLaunchPosition()
    log("Torpedo " .. name .. " launched! Search depth: " .. obj.targetDepth .. "m | Battery: " .. obj.batteryLife .. "s", obj.ownerCoalition)

    -- Alert enemy coalition about torpedo launch
    local enemyCoalition = obj.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
    trigger.action.outTextForCoalition(enemyCoalition, "WARNING: Enemy ASW torpedo in the water!", 10, false)

    return obj
end

-- Mark launch position on F10 map
function AntiSubmarineTorpedo:markLaunchPosition()
    local point = {x = self.x, y = 0, z = self.z}
    local green = {0, 1, 0, 1}
    local circleId = nextMarkId()
    trigger.action.circleToAll(-1, circleId, point, 100, green, {0, 1, 0, 0.3}, 1, true)
    local textPoint = {x = self.x + 150, y = 0, z = self.z}
    local textId = nextMarkId()
    trigger.action.textToAll(-1, textId, textPoint, green, {0, 0, 0, 0}, 10, true, "ASW Torpedo Launch")
end

-- Main update loop: runs every second
function AntiSubmarineTorpedo:startUpdateLoop()
    local function update()
        if not self.active then return end

        local currentTime = timer.getTime()
        local dt = currentTime - self.lastUpdateTime
        self.lastUpdateTime = currentTime
        self.elapsedTime = self.elapsedTime + dt

        -- Battery check
        local remaining = self.batteryLife - self.elapsedTime
        if remaining <= 0 then
            self:expire(true)
            return
        end

        -- Move depth toward target
        self:updateDepth(dt)

        -- Try to detect submarines
        self:detectAndHome(dt)

        -- Move forward on current heading
        self:move(dt)

        -- Destroy torpedo if it runs aground
        if self:getWaterDepth() <= 0 then
            log(self.name .. " ran aground and was destroyed.", self.ownerCoalition)
            self:expire(false)
            return
        end

        -- Update map marker
        self:updateMarker()

        -- Log battery timer
        debugMessage(string.format("%s | Battery: %.0fs | Depth: %.0fm | Hdg: %.0f°",
            self.name, remaining, self.depth, self.heading), 1)

        self.updateScheduleId = timer.scheduleFunction(function()
            update()
        end, nil, timer.getTime() + 1)
    end

    update()
end

function AntiSubmarineTorpedo:getWaterDepth()
    local _, depth = land.getSurfaceHeightWithSeabed({x = self.x, y = self.z})
    debugMessage("Depth at point: "..depth, 5)
    return math.max(0, depth)
end

-- Move the torpedo forward
function AntiSubmarineTorpedo:move(dt)
    local headingRad = math.rad(self.heading)
    local distance = self.speed * dt
    self.x = self.x + distance * math.cos(headingRad)
    self.z = self.z + distance * math.sin(headingRad)
end

-- Adjust depth toward targetDepth
function AntiSubmarineTorpedo:updateDepth(dt)
    local depthDiff = self.targetDepth - self.depth
    if math.abs(depthDiff) > 0.1 then
        local maxChange = self.depthRate * dt
        if math.abs(depthDiff) <= maxChange then
            self.depth = self.targetDepth
        elseif depthDiff > 0 then
            self.depth = self.depth + maxChange
        else
            self.depth = self.depth - maxChange
        end
    end
end

-- Detect submarines and home in on nearest contact
function AntiSubmarineTorpedo:detectAndHome(dt)
    local bestContact = nil
    local bestDist = math.huge

    for _, sub in ipairs(self.submarines) do
        if sub:isAlive() then
            -- Check for kill first (using true positions)
            local dx = sub.x - self.x
            local dz = sub.z - self.z
            local horizontalDist = math.sqrt(dx * dx + dz * dz)
            local depthDiff = math.abs(sub.depth - self.depth)

            if horizontalDist <= self.killRadius and depthDiff <= self.depthTolerance then
                self:hitTarget(sub)
                return
            end

            -- Try sonar detection
            local contact = self:tryDetect(sub)
            if contact then
                local cdx = contact.x - self.x
                local cdz = contact.z - self.z
                local contactDist = math.sqrt(cdx * cdx + cdz * cdz)
                if contactDist < bestDist then
                    bestDist = contactDist
                    bestContact = contact
                end
            end
        end
    end

    if bestContact then
        if not self.hasTarget then
            log(self.name .. " SONAR CONTACT! Homing on target!", self.ownerCoalition)
        end
        self.hasTarget = true
        -- Homing ping sound every 3 seconds (both coalitions)
        local now = timer.getTime()
        if now - self.lastHomingPingTime >= 3 then
            self.lastHomingPingTime = now
            if ASW_SOUND then
                local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
                ASW_SOUND:playForCoalition(self.ownerCoalition, "torpedo_homing")
                ASW_SOUND:playForCoalition(enemyCoalition, "torpedo_homing")
            end
        end
        -- Store last known position
        self.lastContactX = bestContact.x
        self.lastContactZ = bestContact.z
        self.lastContactDepth = bestContact.depth
        -- Home toward nearest detected contact
        self:homeOnContact(bestContact, dt)
    elseif self.hasTarget and self.lastContactX then
        -- No detection: turn toward last known position
        self:homeOnContact({
            x = self.lastContactX,
            z = self.lastContactZ,
            depth = self.lastContactDepth
        }, dt)
    end
end

-- Active sonar detection: ping bounces off hull regardless of sub movement.
-- Movement adds a bonus (cavitation, Doppler) but a stationary sub is still detectable.
function AntiSubmarineTorpedo:tryDetect(sub)
    local dx = sub.x - self.x
    local dz = sub.z - self.z
    local distance = math.sqrt(dx * dx + dz * dz)

    if distance > self.maxDetectionRange then return nil end

    -- Active sonar: base reflection from hull + bonus from movement noise
    local baseReflection = 1.0  -- hull always reflects the ping
    local movementBonus = sub.speed * sub.noiseFactor * 0.5  -- moving subs are easier
    local effectiveSignal = baseReflection + movementBonus

    local maxEffectiveDepth = 500
    local depthPenalty = math.max(0.1, 1 - (sub.depth / maxEffectiveDepth))

    local thermalPenalty = 1.0
    local torpedoBelowLayer = self.depth > self.thermalLayerDepth
    local subBelowLayer = sub.depth > self.thermalLayerDepth
    if torpedoBelowLayer ~= subBelowLayer then
        thermalPenalty = 0.2
    end

    local distanceFactor = 1 - (distance / self.maxDetectionRange)

    local scaleFactor = 0.20
    local probability = effectiveSignal * depthPenalty * thermalPenalty * distanceFactor * scaleFactor
    probability = math.min(0.95, math.max(0, probability))

    debugMessage(self.name .. " sonar -> " .. sub.name .. " dist=" .. string.format("%.0f", distance) .. "m prob=" .. string.format("%.2f", probability))

    if math.random() > probability then return nil end

    -- Detection successful - estimate position with uncertainty
    local confidence = probability
    local bearingTrue = math.atan2(dz, dx)

    local bearingErrorMax = math.rad(30) * (1 - confidence)
    local bearingError = (math.random() * 2 - 1) * bearingErrorMax
    local estimatedBearing = bearingTrue + bearingError

    local rangeErrorMax = distance * 0.25 * (1 - confidence)
    local rangeError = (math.random() * 2 - 1) * rangeErrorMax
    local estimatedRange = math.max(0, distance + rangeError)

    local estimatedX = self.x + estimatedRange * math.cos(estimatedBearing)
    local estimatedZ = self.z + estimatedRange * math.sin(estimatedBearing)

    local depthErrorMax = sub.depth * 0.30 * (1 - confidence)
    local depthError = (math.random() * 2 - 1) * depthErrorMax
    local estimatedDepth = math.max(0, sub.depth + depthError)

    return {
        x = estimatedX,
        z = estimatedZ,
        depth = estimatedDepth,
        confidence = confidence
    }
end

-- Turn toward estimated contact position and adjust depth
function AntiSubmarineTorpedo:homeOnContact(contact, dt)
    -- Adjust target depth toward estimated contact depth
    self.targetDepth = contact.depth

    -- Turn toward estimated contact position
    local dx = contact.x - self.x
    local dz = contact.z - self.z
    local desiredHeading = math.deg(math.atan2(dz, dx))
    if desiredHeading < 0 then desiredHeading = desiredHeading + 360 end

    local headingDiff = desiredHeading - self.heading
    -- Normalize to -180..180
    if headingDiff > 180 then headingDiff = headingDiff - 360 end
    if headingDiff < -180 then headingDiff = headingDiff + 360 end

    local maxTurn = self.turnRate * dt
    if math.abs(headingDiff) <= maxTurn then
        self.heading = desiredHeading
    elseif headingDiff > 0 then
        self.heading = self.heading + maxTurn
    else
        self.heading = self.heading - maxTurn
    end

    -- Normalize heading to 0..360
    if self.heading >= 360 then self.heading = self.heading - 360 end
    if self.heading < 0 then self.heading = self.heading + 360 end
end

-- Torpedo hit: destroy the target (submarine or noise maker)
function AntiSubmarineTorpedo:hitTarget(sub)
    self.active = false
    self:stopUpdateLoop()

    -- Check if we hit a noise maker (decoy) instead of a real sub
    local isDecoy = (sub.remove ~= nil and sub.driftHeading ~= nil)

    -- Remove all trail lines and text
    self:clearMarker()

    if isDecoy then
        local point = {x = sub.x, y = 0, z = sub.z}
        trigger.action.explosion(point, 1000)
        sub:remove()
        logAll("*** TORPEDO IMPACT! " .. self.name .. " hit a decoy! ***", 15)
        local text = self.name .. " | IMPACT | DECOY DESTROYED"
        local coord = COORDINATE:New(sub.x, 0, sub.z)
        self.impactMarker = MARKER:New(coord, text):ReadOnly():ToAll()
    else
        local point = {x = sub.x, y = 0, z = sub.z}
        trigger.action.explosion(point, 1000)
        sub:destroy()
        logAll("*** TORPEDO IMPACT! " .. self.name .. " has destroyed " .. sub.name .. "! ***", 30)
        local text = self.name .. " | IMPACT | " .. sub.name .. " DESTROYED"
        local coord = COORDINATE:New(sub.x, 0, sub.z)
        self.impactMarker = MARKER:New(coord, text):ReadOnly():ToAll()
    end
end

-- Battery expired or torpedo destroyed
function AntiSubmarineTorpedo:expire(isBatteryExpired)
    self.active = false
    self:stopUpdateLoop()
    self:clearMarker()
    if isBatteryExpired then
        log(self.name .. " battery depleted. Torpedo lost.", self.ownerCoalition)
    end
end

-- Remove torpedo (e.g. on cleanup)
function AntiSubmarineTorpedo:remove()
    self.active = false
    self:stopUpdateLoop()
    self:clearMarker()
end

function AntiSubmarineTorpedo:isActive()
    return self.active
end

function AntiSubmarineTorpedo:stopUpdateLoop()
    if self.updateScheduleId then
        timer.removeFunction(self.updateScheduleId)
        self.updateScheduleId = nil
    end
end

-- Update F10 map marker as line trail showing torpedo position
function AntiSubmarineTorpedo:updateMarker()
    local currentTime = timer.getTime()
    -- Only create new marker every 20 seconds
    if currentTime - self.lastMarkerTime < 20 then
        return
    end
    self.lastMarkerTime = currentTime

    -- Draw line segment from previous position to current position
    local startPoint = {x = self.prevMarkerX, y = 0, z = self.prevMarkerZ}
    local endPoint = {x = self.x, y = 0, z = self.z}
    local lineId = nextMarkId()
    trigger.action.lineToAll(-1, lineId, startPoint, endPoint, {1, 0, 0, 1}, 1, true)
    self.markerIds[#self.markerIds + 1] = lineId

    -- Remove old text marker
    if self.textMarkerId then
        trigger.action.removeMark(self.textMarkerId)
    end

    -- Place text label at current position
    local remaining = math.max(0, self.batteryLife - self.elapsedTime)
    local status = self.hasTarget and "HOMING" or "SEARCHING"
    local text = string.format("%s | %s | Depth: %.0fm | Hdg: %.0f° | Battery: %.0fs",
        self.name, status, self.depth, self.heading, remaining)
    local textId = nextMarkId()
    trigger.action.textToAll(-1, textId, endPoint, {1, 0, 0, 1}, {0, 0, 0, 0}, 12, true, text)
    self.textMarkerId = textId
    self.markerIds[#self.markerIds + 1] = textId

    -- Update previous position
    self.prevMarkerX = self.x
    self.prevMarkerZ = self.z
end

-- Remove all map markers (lines and text)
function AntiSubmarineTorpedo:clearMarker()
    for _, id in ipairs(self.markerIds) do
        trigger.action.removeMark(id)
    end
    self.markerIds = {}
    self.textMarkerId = nil
end

-- ===========================================================================
-- submarineTorpedo.lua
-- ===========================================================================

SubmarineTorpedo = {}
SubmarineTorpedo.__index = SubmarineTorpedo

local function log(message, logCoalition, duration)
    duration = duration or 10
    trigger.action.outTextForCoalition(logCoalition, message, duration, false)
    env.info(message, false)
end

local function logAll(message, duration)
    duration = duration or 10
    trigger.action.outText(message, duration, false)
    env.info(message, false)
end

local function debugMessage(message, duration)
    if trigger.misc.getUserFlag("Debug") == 1 then
        duration = duration or 10
        trigger.action.outText(message, duration, false)
        env.info(message, false)
    end
end

if not _torpedoMarkIdCounter then _torpedoMarkIdCounter = 100000 end
local function nextMarkId()
    _torpedoMarkIdCounter = _torpedoMarkIdCounter + 1
    return _torpedoMarkIdCounter
end

-- Constructor
-- name: Identifier (e.g. "Kursk-Torpedo-1")
-- x, z: DCS world coordinates at launch (submarine position)
-- heading: Initial heading in degrees (submarine heading)
-- ownerCoalition: coalition that fired the torpedo (e.g. RED)
-- targetCoalition: coalition whose ships to target (e.g. BLUE)
-- buoys: table of Sonarbuoy instances (for launch detection alert)
function SubmarineTorpedo:new(name, x, z, heading, ownerCoalition, targetCoalition, buoys)
    local obj = {
        name = name,
        x = x,
        z = z,
        heading = heading,
        speed = 20.58,              -- 40 knots in m/s
        turnRate = 3,               -- degrees per second
        maxDetectionRange = 10000,  -- 10 km sonar range
        coneHalfAngle = 30,         -- ±30° forward sonar cone
        killRadius = 50,            -- meters
        armingTime = 5,             -- seconds before warhead arms
        batteryLife = 300,          -- 5 minutes
        explosionPower = 5000,      -- DCS explosion power
        ownerCoalition = ownerCoalition,
        targetCoalition = targetCoalition,
        active = true,
        armed = false,
        hasTarget = false,
        lastContactX = nil,
        lastContactZ = nil,
        elapsedTime = 0,
        lastUpdateTime = timer.getTime(),
        lastMarkerTime = 0,         -- Track when last marker was created
        lastHomingPingTime = 0,      -- Track homing ping interval
        prevMarkerX = x,
        prevMarkerZ = z,
        markerIds = {},
        textMarkerId = nil,
        updateScheduleId = nil
    }
    setmetatable(obj, SubmarineTorpedo)

    -- Alert any buoys in range about the torpedo launch
    obj:alertBuoys(buoys)

    obj:startUpdateLoop()
    obj:markLaunchPosition()
    log(name .. " launched! Heading: " .. string.format("%.0f", heading) .. "°", ownerCoalition)
    return obj
end

-- Check all buoys: if launch position is within a buoy's detection range,
-- mark the exact launch position with 100% confidence for the buoy's coalition
function SubmarineTorpedo:alertBuoys(buoys)
    if not buoys then return end
    for _, buoy in ipairs(buoys) do
        if buoy:isActive() then
            local dx = self.x - buoy.x
            local dz = self.z - buoy.z
            local dist = math.sqrt(dx * dx + dz * dz)
            if dist <= buoy.maxDetectionRange then
                local coord = COORDINATE:New(self.x, 0, self.z)
                local text = buoy.name .. " | TORPEDO LAUNCH DETECTED | Confidence: 100%"
                local marker = MARKER:New(coord, text):ReadOnly():ToCoalition(buoy.ownerCoalition)
                timer.scheduleFunction(function()
                    marker:Remove()
                end, nil, timer.getTime() + 30)
                log(buoy.name .. " detected TORPEDO LAUNCH at close range!", buoy.ownerCoalition)
            end
        end
    end
end

-- Mark launch position on F10 map
function SubmarineTorpedo:markLaunchPosition()
    local point = {x = self.x, y = 0, z = self.z}
    local green = {0, 1, 0, 1}
    local circleId = nextMarkId()
    trigger.action.circleToAll(-1, circleId, point, 100, green, {0, 1, 0, 0.3}, 1, true)
    local textPoint = {x = self.x + 150, y = 0, z = self.z}
    local textId = nextMarkId()
    trigger.action.textToAll(-1, textId, textPoint, green, {0, 0, 0, 0}, 10, true, "Submarine Torpedo Launch")
end

-- Main update loop: runs every second
function SubmarineTorpedo:startUpdateLoop()
    local function update()
        if not self.active then return end

        local currentTime = timer.getTime()
        local dt = currentTime - self.lastUpdateTime
        self.lastUpdateTime = currentTime
        self.elapsedTime = self.elapsedTime + dt

        -- Battery check
        local remaining = self.batteryLife - self.elapsedTime
        if remaining <= 0 then
            self:expire(true)
            return
        end

        -- Check arming
        if not self.armed and self.elapsedTime >= self.armingTime then
            self.armed = true
            debugMessage(self.name .. " ARMED")
        end

        -- If armed, check proximity kill against all enemy ships
        if self.armed then
            local killed = self:checkProximityKill()
            if killed then return end
        end

        -- Detect in sonar cone and home
        self:detectAndHome(dt)

        -- Move forward
        self:move(dt)

        -- Destroy torpedo if it runs aground
        if self:getWaterDepth() <= 0 then
            log(self.name .. " ran aground and was destroyed.", self.ownerCoalition)
            self:expire(false)
            return
        end

        -- Update map marker (visible to all)
        self:updateMarker()

        debugMessage(string.format("%s | Battery: %.0fs | Hdg: %.0f° | %s",
            self.name, remaining, self.heading,
            self.armed and "ARMED" or "ARMING..."), 1)

        self.updateScheduleId = timer.scheduleFunction(function()
            update()
        end, nil, timer.getTime() + 1)
    end

    update()
end

function SubmarineTorpedo:getWaterDepth()
    local _, depth = land.getSurfaceHeightWithSeabed({x = self.x, y = self.z})
    debugMessage("Depth at point: "..depth, 5)
    return math.max(0, depth)
end

-- Move the torpedo forward
function SubmarineTorpedo:move(dt)
    local headingRad = math.rad(self.heading)
    local distance = self.speed * dt
    self.x = self.x + distance * math.cos(headingRad)
    self.z = self.z + distance * math.sin(headingRad)
end

-- Find all ship units in the target coalition
function SubmarineTorpedo:findShipTargets()
    local targets = {}
    local groups = coalition.getGroups(self.targetCoalition, Group.Category.SHIP)
    if groups then
        for _, group in ipairs(groups) do
            if group and group:isExist() then
                local units = group:getUnits()
                if units then
                    for _, unit in ipairs(units) do
                        if unit and unit:isExist() then
                            targets[#targets + 1] = unit
                        end
                    end
                end
            end
        end
    end
    return targets
end

-- Check if any enemy ship is within kill radius (proximity fuse, no cone needed)
function SubmarineTorpedo:checkProximityKill()
    local targets = self:findShipTargets()
    for _, unit in ipairs(targets) do
        local pos = unit:getPoint()
        local dx = pos.x - self.x
        local dz = pos.z - self.z
        local dist = math.sqrt(dx * dx + dz * dz)
        if dist <= self.killRadius then
            self:hitTarget(unit)
            return true
        end
    end
    return false
end

-- Detect ships in sonar cone and home on nearest contact
function SubmarineTorpedo:detectAndHome(dt)
    local targets = self:findShipTargets()
    local detected = false
    local nearestContact = nil
    local nearestDist = self.maxDetectionRange + 1

    for _, unit in ipairs(targets) do
        local contact = self:tryDetectShip(unit)
        if contact and contact.distance < nearestDist then
            nearestDist = contact.distance
            nearestContact = contact
        end
    end

    if nearestContact then
        if not self.hasTarget then
            log(self.name .. " SONAR CONTACT! Homing on target: " .. nearestContact.unitName .. " at distance " .. string.format("%.0f", nearestContact.distance) .. "m", self.ownerCoalition, 30)
        end
        self.hasTarget = true
        detected = true
        -- Homing ping sound every 3 seconds (both coalitions)
        local now = timer.getTime()
        if now - self.lastHomingPingTime >= 3 then
            self.lastHomingPingTime = now
            if ASW_SOUND then
                ASW_SOUND:playForCoalition(self.ownerCoalition, "torpedo_homing")
                ASW_SOUND:playForCoalition(self.targetCoalition, "torpedo_homing")
            end
        end
        self.lastContactX = nearestContact.x
        self.lastContactZ = nearestContact.z
        self:homeOnPosition(nearestContact.x, nearestContact.z, dt)
    end

    -- No detection this tick: turn toward last known position
    if not detected and self.hasTarget and self.lastContactX then
        self:homeOnPosition(self.lastContactX, self.lastContactZ, dt)
    end
end

-- Sonar detection: forward cone with probability based on distance
function SubmarineTorpedo:tryDetectShip(unit)
    local pos = unit:getPoint()
    local dx = pos.x - self.x
    local dz = pos.z - self.z
    local distance = math.sqrt(dx * dx + dz * dz)

    if distance > self.maxDetectionRange then return nil end

    -- Check sonar cone (±30° from heading)
    local bearingToTarget = math.deg(math.atan2(dz, dx))
    if bearingToTarget < 0 then bearingToTarget = bearingToTarget + 360 end
    local angleDiff = bearingToTarget - self.heading
    if angleDiff > 180 then angleDiff = angleDiff - 360 end
    if angleDiff < -180 then angleDiff = angleDiff + 360 end
    if math.abs(angleDiff) > self.coneHalfAngle then return nil end

    -- Probability based on distance (ships are loud surface targets)
    local distanceFactor = 1 - (distance / self.maxDetectionRange)
    local probability = 0.8 * distanceFactor
    probability = math.min(0.95, math.max(0, probability))

    debugMessage(self.name .. " sonar -> " .. unit:getName() .. " dist=" .. string.format("%.0f", distance) .. "m prob=" .. string.format("%.2f", probability))

    if math.random() > probability then return nil end

    return {
        x = pos.x,
        z = pos.z,
        distance = distance,
        unitName = unit:getName()
    }
end

-- Turn toward a target position
function SubmarineTorpedo:homeOnPosition(targetX, targetZ, dt)
    local dx = targetX - self.x
    local dz = targetZ - self.z
    local desiredHeading = math.deg(math.atan2(dz, dx))
    if desiredHeading < 0 then desiredHeading = desiredHeading + 360 end

    local headingDiff = desiredHeading - self.heading
    if headingDiff > 180 then headingDiff = headingDiff - 360 end
    if headingDiff < -180 then headingDiff = headingDiff + 360 end

    local maxTurn = self.turnRate * dt
    if math.abs(headingDiff) <= maxTurn then
        self.heading = desiredHeading
    elseif headingDiff > 0 then
        self.heading = self.heading + maxTurn
    else
        self.heading = self.heading - maxTurn
    end

    if self.heading >= 360 then self.heading = self.heading - 360 end
    if self.heading < 0 then self.heading = self.heading + 360 end
end

-- Torpedo hit: explode on the ship and destroy it
function SubmarineTorpedo:hitTarget(unit)
    self.active = false
    self:stopUpdateLoop()

    local pos = unit:getPoint()
    local unitName = unit:getName()

    -- Explosion for visual effect and damage
    trigger.action.explosion(pos, self.explosionPower)

    -- Ensure destruction
    if unit:isExist() then
        unit:destroy()
    end

    -- Global message
    logAll("*** TORPEDO IMPACT! " .. self.name .. " has hit " .. unitName .. "! ***", 30)

    -- Remove all trail lines and text
    self:clearMarker()

    -- Place impact marker at hit position
    local impactPoint = {x = pos.x, y = 0, z = pos.z}
    local text = self.name .. " | IMPACT | " .. unitName .. " DESTROYED"
    local coord = COORDINATE:New(pos.x, 0, pos.z)
    self.impactMarker = MARKER:New(coord, text):ReadOnly():ToAll()
end

-- Battery expired or torpedo destroyed
function SubmarineTorpedo:expire(isBatteryExpired)
    self.active = false
    self:stopUpdateLoop()
    self:clearMarker()
    if isBatteryExpired then
        log(self.name .. " battery depleted. Torpedo lost.", self.ownerCoalition)
    end
end

-- Remove torpedo
function SubmarineTorpedo:remove()
    self.active = false
    self:stopUpdateLoop()
    self:clearMarker()
end

function SubmarineTorpedo:isActive()
    return self.active
end

function SubmarineTorpedo:stopUpdateLoop()
    if self.updateScheduleId then
        timer.removeFunction(self.updateScheduleId)
        self.updateScheduleId = nil
    end
end

-- Update F10 map marker as line trail (visible to all coalitions)
function SubmarineTorpedo:updateMarker()
    local currentTime = timer.getTime()
    -- Only create new marker every 20 seconds
    if currentTime - self.lastMarkerTime < 20 then
        return
    end
    self.lastMarkerTime = currentTime

    -- Draw line segment from previous position to current position
    local startPoint = {x = self.prevMarkerX, y = 0, z = self.prevMarkerZ}
    local endPoint = {x = self.x, y = 0, z = self.z}
    local lineId = nextMarkId()
    trigger.action.lineToAll(-1, lineId, startPoint, endPoint, {1, 0, 0, 1}, 1, true)
    self.markerIds[#self.markerIds + 1] = lineId

    -- Remove old text marker
    if self.textMarkerId then
        trigger.action.removeMark(self.textMarkerId)
    end

    -- Place text label at current position
    local remaining = math.max(0, self.batteryLife - self.elapsedTime)
    local status = "SEARCHING"
    if not self.armed then
        status = "ARMING"
    elseif self.hasTarget then
        status = "HOMING"
    end
    local text = string.format("%s | %s | Hdg: %.0f° | Battery: %.0fs",
        self.name, status, self.heading, remaining)
    local textId = nextMarkId()
    trigger.action.textToAll(-1, textId, endPoint, {1, 0, 0, 1}, {0, 0, 0, 0}, 12, true, text)
    self.textMarkerId = textId
    self.markerIds[#self.markerIds + 1] = textId

    -- Update previous position
    self.prevMarkerX = self.x
    self.prevMarkerZ = self.z
end

-- Remove all map markers (lines and text)
function SubmarineTorpedo:clearMarker()
    for _, id in ipairs(self.markerIds) do
        trigger.action.removeMark(id)
    end
    self.markerIds = {}
    self.textMarkerId = nil
end

-- ===========================================================================
-- dippingSonar.lua
-- ===========================================================================

DippingSonar = {}
DippingSonar.__index = DippingSonar

local function log(message, logCoalition, duration)
    duration = duration or 10
    trigger.action.outTextForCoalition(logCoalition, message, duration, false)
    env.info(message, false)
end

local function logAll(message, duration)
    duration = duration or 10
    trigger.action.outText(message, duration, false)
    env.info(message, false)
end

local function debugMessage(message, duration)
    if trigger.misc.getUserFlag("Debug") == 1 then
        duration = duration or 10
        trigger.action.outText(message, duration, false)
        env.info(message, false)
    end
end

-- Constructor
-- groupName: the ASW hunter group name that owns this sonar
-- ownerCoalition: coalition side
-- thermalLayerDepth: thermal layer depth for detection
-- submarines: shared table of detectable objects
function DippingSonar:new(groupName, ownerCoalition, thermalLayerDepth, submarines)
    local obj = {
        groupName = groupName,
        ownerCoalition = ownerCoalition or coalition.side.BLUE,
        thermalLayerDepth = thermalLayerDepth or 90,
        submarines = submarines or {},
        maxDetectionRange = 8000,    -- 8 km active sonar range
        scaleFactor = 0.25,          -- higher than buoy (0.15)
        maxCableLength = 450,        -- max cable length in meters
        cableRate = 5,               -- meters per second lower/raise
        maxSpeed = 15,               -- m/s before cable breaks
        warnSpeed = 5,               -- m/s speed warning threshold
        maxAltitude = 100,           -- AGL before cable breaks
        warnAltitude = 50,           -- AGL altitude warning threshold
        detectInterval = 3,          -- seconds between pings
        targetCableLength = 100,     -- cable length to pay out
        currentCableLength = 0,      -- cable length currently paid out
        state = "stowed",            -- stowed, lowering, active, raising, broken
        operational = true,          -- false if cable broke
        contactMarkers = {},
        updateScheduleId = nil
    }
    setmetatable(obj, DippingSonar)
    return obj
end

-- Get the DCS unit for this sonar's group
function DippingSonar:getUnit()
    local dcsGroup = Group.getByName(self.groupName)
    if not dcsGroup or not dcsGroup:isExist() then return nil end
    local units = dcsGroup:getUnits()
    if units and #units > 0 and units[1]:isExist() then
        return units[1]
    end
    return nil
end

-- Get unit's AGL altitude
function DippingSonar:getAGL(unit)
    local pos = unit:getPoint()
    local landHeight = land.getHeight({x = pos.x, y = pos.z})
    return pos.y - landHeight
end

-- Get unit's speed in m/s
function DippingSonar:getSpeed(unit)
    local velocity = unit:getVelocity()
    return math.sqrt(velocity.x^2 + velocity.y^2 + velocity.z^2)
end

-- Set target cable length
function DippingSonar:setDepth(length)
    self.targetCableLength = math.max(0, math.min(length, self.maxCableLength))
end

-- Adjust target cable length by a delta (+extend / -retract)
function DippingSonar:adjustCable(delta)
    self.targetCableLength = math.max(0, math.min(self.targetCableLength + delta, self.maxCableLength))
end

-- Get water (seabed) depth at the helicopter's current position
function DippingSonar:getSeabedDepth(unit)
    unit = unit or self:getUnit()
    if not unit then return 0 end
    local pos = unit:getPoint()
    local _, depth = land.getSurfaceHeightWithSeabed({x = pos.x, y = pos.z})
    return math.max(0, depth)
end

-- Get actual sonar depth in water = cable length - AGL (clamped >= 0)
function DippingSonar:getWaterDepth(unit)
    unit = unit or self:getUnit()
    if not unit then return 0 end
    local agl = self:getAGL(unit)
    return math.max(0, self.currentCableLength - agl)
end

-- Lower the sonar
function DippingSonar:lower()
    if not self.operational then return false, "Dipping sonar is broken! Return to rearm." end
    if self.state ~= "stowed" then return false, "Sonar is already deployed!" end

    local unit = self:getUnit()
    if unit and self:getSeabedDepth(unit) <= 0 then
        return false, "Cannot deploy dipping sonar over land!"
    end

    self.state = "lowering"
    self.currentCableLength = 0
    self:startUpdateLoop()
    return true, "Lowering dipping sonar, cable to " .. self.targetCableLength .. "m..."
end

-- Raise the sonar
function DippingSonar:raise()
    if self.state ~= "active" and self.state ~= "lowering" then
        return false, "Sonar is not deployed!"
    end

    self.state = "raising"
    return true, "Raising dipping sonar..."
end

-- Stop the sonar at current cable length
function DippingSonar:stop()
    if self.state ~= "lowering" and self.state ~= "raising" then
        return false, "Sonar is not moving!"
    end

    self.state = "active"
    self.targetCableLength = self.currentCableLength
    local waterDepth = self:getWaterDepth()
    return true, string.format("Sonar stopped. Cable: %.0fm | Sonar depth: %.0fm", self.currentCableLength, waterDepth)
end

-- Repair the sonar (at rearm point)
function DippingSonar:repair()
    self.operational = true
    self.state = "stowed"
    self.currentCableLength = 0
end

function DippingSonar:isDeployed()
    return self.state == "lowering" or self.state == "active" or self.state == "raising"
end

-- Main update loop
function DippingSonar:startUpdateLoop()
    local function update()
        if self.state == "stowed" or self.state == "broken" then return end

        local unit = self:getUnit()
        if not unit then
            self:breakCable("Aircraft lost!")
            return
        end

        -- Check speed and altitude limits
        local speed = self:getSpeed(unit)
        local agl = self:getAGL(unit)
        local seabedDepth = self:getSeabedDepth(unit)

        -- Speed warnings and break
        if speed > self.maxSpeed then
            self:breakCable("Cable snapped! Speed too high (" .. string.format("%.0f", speed) .. " m/s)!")
            return
        elseif speed > self.warnSpeed then
            self:messageToGroup("WARNING: Speed " .. string.format("%.0f", speed) .. " m/s! Cable breaks at " .. self.maxSpeed .. " m/s!", 1)
        end

        -- Altitude warnings and break
        if agl > self.maxAltitude then
            self:breakCable("Cable snapped! Altitude too high (" .. string.format("%.0f", agl) .. "m AGL)!")
            return
        elseif agl > self.warnAltitude then
            self:messageToGroup("WARNING: Altitude " .. string.format("%.0f", agl) .. "m AGL! Cable breaks at " .. self.maxAltitude .. "m!", 1)
        end

        -- Destroy sonar if helicopter flies over land while deployed
        if seabedDepth <= 0 then
            self:breakCable("Sonar destroyed! Helicopter flew over land!")
            return
        end

        -- Update cable length
        local cableStep = self.cableRate * self.detectInterval
        if self.state == "lowering" then
            self.currentCableLength = self.currentCableLength + cableStep
            if self.currentCableLength >= self.targetCableLength then
                self.currentCableLength = self.targetCableLength
                self.state = "active"
                local waterDepth = self:getWaterDepth(unit)
                self:messageToGroup(string.format("Dipping sonar active. Cable: %dm | Sonar depth: %.0fm", self.currentCableLength, waterDepth), 5)
                -- Splash sound when sonar enters water (hunter group + enemy coalition)
                if ASW_SOUND then
                    ASW_SOUND:playOnce(self.groupName, "sonar_splash")
                    local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
                    ASW_SOUND:playForCoalition(self.ownerCoalition, "sonar_splash")
                    ASW_SOUND:playForCoalition(enemyCoalition, "sonar_splash")
                end
            else
                self:messageToGroup(string.format("Lowering... Cable: %.0fm / %dm", self.currentCableLength, self.targetCableLength), 1)
                -- Cable extending sound (hunter group only)
                if ASW_SOUND then
                    ASW_SOUND:playOnce(self.groupName, "sonar_extend")
                end
            end
        elseif self.state == "raising" then
            self.currentCableLength = self.currentCableLength - cableStep
            if self.currentCableLength <= 0 then
                self.currentCableLength = 0
                self.state = "stowed"
                self:messageToGroup("Dipping sonar stowed.", 5)
                return -- Stop the loop
            else
                self:messageToGroup(string.format("Raising... Cable: %.0fm", self.currentCableLength), 1)
                -- Cable retrieving sound (hunter group only)
                if ASW_SOUND then
                    ASW_SOUND:playOnce(self.groupName, "sonar_retrieve")
                end
            end
        elseif self.state == "active" then
            -- Adjust cable if target changed while active
            local cableDiff = self.targetCableLength - self.currentCableLength
            if math.abs(cableDiff) > 0.1 then
                local change = cableStep
                if math.abs(cableDiff) <= change then
                    self.currentCableLength = self.targetCableLength
                elseif cableDiff > 0 then
                    self.currentCableLength = self.currentCableLength + change
                else
                    self.currentCableLength = self.currentCableLength - change
                end
                local waterDepth = self:getWaterDepth(unit)
                self:messageToGroup(string.format("Adjusting cable... %.0fm / %dm | Sonar depth: %.0fm", self.currentCableLength, self.targetCableLength, waterDepth), 1)
            end

            -- Ping for submarines
            self:ping(unit)
        end

        -- Clamp cable if water is shallower than current sonar depth
        local sonarWaterDepth = self.currentCableLength - agl
        if sonarWaterDepth > seabedDepth then
            self.currentCableLength = agl + seabedDepth
            self:messageToGroup(string.format("WARNING: Water depth (%.0fm) shallower than sonar depth (%.0fm). Cable adjusted to %.0fm.", seabedDepth, sonarWaterDepth, self.currentCableLength), 3)
        end

        self.updateScheduleId = timer.scheduleFunction(function()
            update()
        end, nil, timer.getTime() + self.detectInterval)
    end

    update()
end

-- Active sonar ping: detect submarines
function DippingSonar:ping(unit)
    local pos = unit:getPoint()
    local sonarX = pos.x
    local sonarZ = pos.z

    -- Sonar ping sound (hunter group + warning to enemy coalition)
    if ASW_SOUND then
        ASW_SOUND:playOnce(self.groupName, "sonar_ping")
        ASW_SOUND:playForCoalition(self.ownerCoalition, "sonar_ping")
    end

    -- Alert enemy coalition about active sonar ping with position
    local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
    if ASW_SOUND then
        ASW_SOUND:playForCoalition(enemyCoalition, "warning_sonar")
    end
    local coord = COORDINATE:New(sonarX, 0, sonarZ)
    local coordText = coord:ToStringLLDMS()
    trigger.action.outTextForCoalition(enemyCoalition,
        "ACTIVE SONAR PING DETECTED!\nPosition: " .. coordText, 5, false)

    for _, sub in ipairs(self.submarines) do
        if sub:isAlive() then
            local contact = self:tryDetect(sub, sonarX, sonarZ)
            if contact then
                self:markContact(contact)
                log(self.groupName .. " dipping sonar CONTACT! Confidence: " .. string.format("%.0f", contact.confidence * 100) .. "%", self.ownerCoalition)
            end
        end
    end
end

-- Active sonar detection: ping bounces off hull regardless of sub movement.
-- Movement adds a bonus (cavitation, Doppler) but a stationary sub is still detectable.
function DippingSonar:tryDetect(sub, sonarX, sonarZ)
    local dx = sub.x - sonarX
    local dz = sub.z - sonarZ
    local distance = math.sqrt(dx * dx + dz * dz)

    if distance > self.maxDetectionRange then return nil end

    -- Active sonar: base reflection from hull + bonus from movement noise
    local baseReflection = 1.0  -- hull always reflects the ping
    local movementBonus = sub.speed * sub.noiseFactor * 0.5  -- moving subs are easier
    local effectiveSignal = baseReflection + movementBonus

    local maxEffectiveDepth = 500
    local depthPenalty = math.max(0.1, 1 - (sub.depth / maxEffectiveDepth))

    local thermalPenalty = 1.0
    local waterDepth = self:getWaterDepth()
    if sub.depth > self.thermalLayerDepth and waterDepth <= self.thermalLayerDepth then
        -- Sonar above layer, sub below: reduced
        thermalPenalty = 0.2
    elseif sub.depth > self.thermalLayerDepth and waterDepth > self.thermalLayerDepth then
        -- Both below layer: no penalty (sonar is down there with the sub)
        thermalPenalty = 1.0
    end

    local distanceFactor = 1 - (distance / self.maxDetectionRange)

    local probability = effectiveSignal * depthPenalty * thermalPenalty * distanceFactor * self.scaleFactor
    probability = math.min(0.95, math.max(0, probability))

    debugMessage(self.groupName .. " dip sonar -> " .. sub.name .. " dist=" .. string.format("%.0f", distance) .. "m prob=" .. string.format("%.2f", probability))

    -- Signal too weak to produce a reliable contact
    if probability < 0.05 then return nil end

    if math.random() > probability then return nil end

    -- Detection successful
    local confidence = probability
    local bearingTrue = math.atan2(dz, dx)

    local bearingErrorMax = math.rad(30) * (1 - confidence)
    local bearingError = (math.random() * 2 - 1) * bearingErrorMax
    local estimatedBearing = bearingTrue + bearingError

    local rangeErrorMax = distance * 0.25 * (1 - confidence)
    local rangeError = (math.random() * 2 - 1) * rangeErrorMax
    local estimatedRange = math.max(0, distance + rangeError)

    local estimatedX = sonarX + estimatedRange * math.cos(estimatedBearing)
    local estimatedZ = sonarZ + estimatedRange * math.sin(estimatedBearing)

    local depthErrorMax = sub.depth * 0.30 * (1 - confidence)
    local depthError = (math.random() * 2 - 1) * depthErrorMax
    local estimatedDepth = math.max(0, sub.depth + depthError)

    return {
        x = estimatedX,
        z = estimatedZ,
        depth = estimatedDepth,
        confidence = confidence,
        subName = sub.name,
        sonarGroup = self.groupName
    }
end

-- Place contact marker (30 second auto-remove, like buoys)
function DippingSonar:markContact(contact)
    local coord = COORDINATE:New(contact.x, 0, contact.z)
    local text = string.format("%s DIPPING SONAR | CONTACT | Confidence: %.0f%% | Est. Depth: %.0fm",
        self.groupName, contact.confidence * 100, contact.depth)
    local marker = MARKER:New(coord, text):ReadOnly():ToCoalition(self.ownerCoalition)
    self.contactMarkers[#self.contactMarkers + 1] = marker

    timer.scheduleFunction(function()
        marker:Remove()
        for i, m in ipairs(self.contactMarkers) do
            if m == marker then
                table.remove(self.contactMarkers, i)
                break
            end
        end
    end, nil, timer.getTime() + 30)
end

-- Cable break
function DippingSonar:breakCable(reason)
    self.state = "broken"
    self.operational = false
    self.currentCableLength = 0
    self:stopUpdateLoop()
    self:clearContactMarkers()
    self:messageToGroup("DIPPING SONAR LOST! " .. reason, 10)
    -- Cable break sound (hunter group only)
    if ASW_SOUND then
        ASW_SOUND:playOnce(self.groupName, "sonar_cable_break")
    end
end

function DippingSonar:stopUpdateLoop()
    if self.updateScheduleId then
        timer.removeFunction(self.updateScheduleId)
        self.updateScheduleId = nil
    end
end

function DippingSonar:clearContactMarkers()
    for _, m in ipairs(self.contactMarkers) do
        m:Remove()
    end
    self.contactMarkers = {}
end

function DippingSonar:messageToGroup(message, duration)
    local mooseGroup = GROUP:FindByName(self.groupName)
    if mooseGroup then
        trigger.action.outTextForGroup(mooseGroup:GetDCSObject():getID(), message, duration or 5, false)
    end
end

-- ===========================================================================
-- depthCharge.lua
-- ===========================================================================

DepthCharge = {}
DepthCharge.__index = DepthCharge

if not _dcMarkIdCounter then _dcMarkIdCounter = 700000 end
local function nextDCMarkId()
    _dcMarkIdCounter = _dcMarkIdCounter + 1
    return _dcMarkIdCounter
end

-- A single depth charge in a drop pattern.
-- Spawning over land discards the charge silently (no explosion, no detonation).
-- Sinks at a fixed rate until reaching setDepth, then detonates.
-- Kills any VirtualSubmarine within killRadius (3D) of the detonation point.
function DepthCharge:new(name, x, z, setDepth, ownerCoalition, submarines)
    -- Discard immediately if spawned over land
    local _, waterDepth = land.getSurfaceHeightWithSeabed({x = x, y = z})
    if waterDepth <= 0 then
        env.info("DepthCharge: " .. name .. " spawned over land — discarded.", false)
        return nil
    end

    local obj = {
        name           = name,
        x              = x,
        z              = z,
        setDepth       = setDepth,
        ownerCoalition = ownerCoalition,
        submarines     = submarines,
        depth          = 0,
        sinkRate       = 3,    -- m/s
        killRadius     = 80,   -- meters (3D)
        active         = true,
        updateScheduleId = nil,
    }
    setmetatable(obj, DepthCharge)
    obj:startSinking()
    return obj
end

function DepthCharge:isActive()
    return self.active
end

function DepthCharge:startSinking()
    local function sink()
        if not self.active then return end
        self.depth = self.depth + self.sinkRate
        if self.depth >= self.setDepth then
            self:detonate()
        else
            self.updateScheduleId = timer.scheduleFunction(function() sink() end, nil, timer.getTime() + 1)
        end
    end
    self.updateScheduleId = timer.scheduleFunction(function() sink() end, nil, timer.getTime() + 1)
end

function DepthCharge:detonate()
    self.active = false

    -- Explosion visual on the water surface
    trigger.action.explosion({x = self.x, y = 1, z = self.z}, 500)

    -- Kill check
    local hit = nil
    for _, sub in ipairs(self.submarines) do
        if sub.maxDepth and sub:isAlive() then
            local dx = sub.x - self.x
            local dz = sub.z - self.z
            local dy = sub.depth - self.setDepth
            local dist3d = math.sqrt(dx * dx + dz * dz + dy * dy)
            if dist3d <= self.killRadius then
                hit = sub
                break
            end
        end
    end

    if hit then
        trigger.action.explosion({x = hit.x, y = 0, z = hit.z}, 1000)
        hit:destroy()

        local text = self.name .. " | DEPTH CHARGE | " .. hit.name .. " DESTROYED"
        local coord = COORDINATE:New(hit.x, 0, hit.z)
        MARKER:New(coord, text):ReadOnly():ToAll()

        trigger.action.outText("*** DEPTH CHARGE! " .. self.name .. " has destroyed " .. hit.name .. "! ***", 30, false)
        env.info("DepthCharge: " .. self.name .. " destroyed " .. hit.name .. " at depth " .. math.floor(self.setDepth) .. "m", false)
    else
        env.info("DepthCharge: " .. self.name .. " detonated at depth " .. math.floor(self.setDepth) .. "m — no kill", false)
    end
end

-- ===========================================================================
-- madDetector.lua
-- ===========================================================================

MADDetector = {}
MADDetector.__index = MADDetector

local function nextMADMarkId()
    if not _madMarkIdCounter then _madMarkIdCounter = 600000 end
    _madMarkIdCounter = _madMarkIdCounter + 1
    return _madMarkIdCounter
end

-- Magnetic Anomaly Detector for fixed-wing ASW aircraft.
-- Detects ferromagnetic submarine hulls by sensing distortions in Earth's
-- magnetic field. Requires low flight directly over the search area.
-- MAD is a close-range precision tool — use sonobuoys first to cue the area,
-- then overfly for a MAD confirmation before torpedo delivery.
--
-- Detection degrades with depth and altitude (inverse-cube physics).
-- Submarines below the searchDepth threshold are undetectable.
-- The charge system represents continuous power draw and sensor heating;
-- deeper search settings require more power and drain faster.
--
-- config table:
--   detectionRange:   horizontal range at optimal altitude (default 500m)
--   maxSearchDepth:   deepest available search depth setting (default 200m)
--   maxAltitude:      max AGL for operation (default 150m)
--   drainBase:        charge drain %/sec at minimum depth (default 0.4)
--   drainPerMeter:    additional drain %/sec per meter of search depth (default 0.004)
--   rechargeRate:     charge recovery %/sec when inactive (default 0.25)
function MADDetector:new(groupName, ownerCoalition, submarines, config)
    config = config or {}
    local obj = {
        groupName       = groupName,
        ownerCoalition  = ownerCoalition,
        submarines      = submarines,
        detectionRange  = config.detectionRange or 500,
        maxSearchDepth  = config.maxSearchDepth  or 200,
        maxAltitude     = config.maxAltitude     or 150,
        drainBase       = config.drainBase       or 0.2,
        drainPerMeter   = config.drainPerMeter   or 0.002,
        rechargeRate    = config.rechargeRate    or 0.25,
        searchDepth     = 100,   -- current setting, default 100m
        charge          = 100,   -- 0-100%
        state           = "inactive",
        scanTick        = 0,
        updateScheduleId = nil,
    }
    setmetatable(obj, MADDetector)
    obj:startUpdateLoop()
    return obj
end

-- ===== CONTROLS =====

function MADDetector:activate()
    if self.state == "active" then
        return false, "MAD already active."
    end
    if self.charge <= 0 then
        return false, "MAD charge depleted — wait for recharge."
    end
    self.state = "active"
    return true, string.format("MAD activated. Search depth: %dm | Drain: %.1f%%/s | Fly below %dm AGL.",
        self.searchDepth, self:getDrainRate(), self.maxAltitude)
end

function MADDetector:deactivate()
    if self.state == "inactive" then
        return false, "MAD already inactive."
    end
    self.state = "inactive"
    return true, string.format("MAD deactivated. Charge: %d%% | Recharging at %.2f%%/s.", math.floor(self.charge), self.rechargeRate)
end

function MADDetector:setSearchDepth(depth)
    self.searchDepth = math.min(depth, self.maxSearchDepth)
    return string.format("MAD search depth: %dm | Drain rate: %.1f%%/s", self.searchDepth, self:getDrainRate())
end

-- ===== INTERNALS =====

function MADDetector:getDrainRate()
    return self.drainBase + self.searchDepth * self.drainPerMeter
end

function MADDetector:getStatusText()
    return string.format("MAD: %s | Charge: %d%% | Depth: %dm | Drain: %.1f%%/s | Max alt: %dm AGL",
        string.upper(self.state), math.floor(self.charge), self.searchDepth,
        self:getDrainRate(), self.maxAltitude)
end

function MADDetector:getUnit()
    local dcsGroup = Group.getByName(self.groupName)
    if not dcsGroup or not dcsGroup:isExist() then return nil end
    local units = dcsGroup:getUnits()
    if units and #units > 0 and units[1]:isExist() then return units[1] end
    return nil
end

function MADDetector:startUpdateLoop()
    local function update()
        if self.state == "active" then
            local unit = self:getUnit()

            -- Drain charge
            self.charge = math.max(0, self.charge - self:getDrainRate())

            if self.charge <= 0 then
                self.state = "inactive"
                local dcsGroup = Group.getByName(self.groupName)
                if dcsGroup and dcsGroup:isExist() then
                    trigger.action.outTextForGroup(dcsGroup:getID(),
                        "MAD charge depleted — system offline. Recharging.", 10, false)
                end
            elseif unit then
                -- Scan and update HUD every 2 seconds
                self.scanTick = self.scanTick + 1
                if self.scanTick >= 2 then
                    self.scanTick = 0
                    self:scan(unit)
                    self:sendStatusHUD(unit)
                end
            end
        else
            -- Recharge while inactive
            self.charge = math.min(100, self.charge + self.rechargeRate)
            self.rechargeTick = (self.rechargeTick or 0) + 1
            if self.rechargeTick >= 5 and self.charge < 100 then
                self.rechargeTick = 0
                local dcsGroup = Group.getByName(self.groupName)
                if dcsGroup and dcsGroup:isExist() then
                    local timeToFull = math.floor((100 - self.charge) / self.rechargeRate)
                    trigger.action.outTextForGroup(dcsGroup:getID(),
                        string.format("MAD RECHARGING | Charge: %d%% (~%ds to full)",
                            math.floor(self.charge), timeToFull), 5, false)
                end
            end
        end

        self.updateScheduleId = timer.scheduleFunction(function() update() end, nil, timer.getTime() + 1)
    end

    timer.scheduleFunction(function() update() end, nil, timer.getTime() + 1)
end

function MADDetector:sendStatusHUD(unit)
    local dcsGroup = Group.getByName(self.groupName)
    if not dcsGroup or not dcsGroup:isExist() then return end

    local pos = unit:getPoint()
    local altAGL = pos.y - land.getHeight({x = pos.x, y = pos.z})
    local timeRemaining = math.floor(self.charge / self:getDrainRate())

    local msg
    if altAGL > self.maxAltitude then
        msg = string.format(
            "MAD SCANNING | Charge: %d%% (~%ds remaining)\nAlt: %.0fm AGL — ABOVE LIMIT (%dm) | NO SIGNAL\nFly lower for effective detection.",
            math.floor(self.charge), timeRemaining, altAGL, self.maxAltitude)
    else
        local altFactor   = math.max(0.1, (50 / math.max(altAGL, 10)) ^ (1/3))
        local effectiveRange = math.floor(self.detectionRange * altFactor)
        local effectiveness  = math.floor(altFactor * 100)
        msg = string.format(
            "MAD SCANNING | Charge: %d%% (~%ds remaining)\nAlt: %.0fm AGL | Range: %dm | Effectiveness: %d%%\nDepth: %dm | Drain: %.1f%%/s",
            math.floor(self.charge), timeRemaining, altAGL,
            effectiveRange, effectiveness,
            self.searchDepth, self:getDrainRate())
    end

    trigger.action.outTextForGroup(dcsGroup:getID(), msg, 2, false)
end

function MADDetector:scan(unit)
    local pos = unit:getPoint()
    local altAGL = pos.y - land.getHeight({x = pos.x, y = pos.z})

    -- MAD range degrades with altitude (inverse cube: range ∝ 1/alt^(1/3))
    -- Reference range at 50m AGL; above maxAltitude the signal is too weak.
    if altAGL > self.maxAltitude then return end
    local altFactor = math.max(0.1, (50 / math.max(altAGL, 10)) ^ (1/3))
    local effectiveRange = self.detectionRange * altFactor

    for _, sub in ipairs(self.submarines) do
        -- Only real submarines (VirtualSubmarine has maxDepth; NoiseMakers do not)
        if sub.maxDepth then
            local dx = sub.x - pos.x
            local dz = sub.z - pos.z
            local dist = math.sqrt(dx * dx + dz * dz)

            if dist <= effectiveRange and sub.depth <= self.searchDepth then
                -- Probability drops off linearly with depth toward searchDepth
                local depthFactor = 1 - (sub.depth / (self.searchDepth + 1))
                local distFactor  = 1 - (dist / effectiveRange) * 0.3
                local probability = 0.9 * depthFactor * distFactor

                -- Signal too weak to produce a reliable contact
                if probability >= 0.05 and math.random() < probability then
                    self:reportContact(sub, dist, altAGL)
                end
            end
        end
    end
end

function MADDetector:reportContact(sub, dist, altAGL)
    -- MAD gives precise horizontal position but cannot determine depth
    local errM = math.max(15, dist * 0.06)
    local contactPoint = {
        x = sub.x + (math.random() - 0.5) * 2 * errM,
        y = 0,
        z = sub.z + (math.random() - 0.5) * 2 * errM,
    }

    local orange     = {1, 0.6, 0, 1}
    local orangeFill = {1, 0.6, 0, 0.2}
    local circleId   = nextMADMarkId()
    local textId     = nextMADMarkId()

    trigger.action.circleToAll(self.ownerCoalition, circleId, contactPoint, 80, orange, orangeFill, 1, true)
    trigger.action.textToAll(self.ownerCoalition, textId,
        {x = contactPoint.x + 100, y = 0, z = contactPoint.z},
        orange, {0, 0, 0, 0}, 10, true,
        "MAD CONTACT | depth unknown | alt " .. math.floor(altAGL) .. "m")

    timer.scheduleFunction(function()
        trigger.action.removeMark(circleId)
        trigger.action.removeMark(textId)
    end, nil, timer.getTime() + 30)

    -- Give submarine side a vague warning (gameplay concession)
    local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
    trigger.action.outTextForCoalition(enemyCoalition, sub.name .. ": magnetic sweep overhead!", 8, false)

    env.info("MAD: contact on " .. (sub.name or "?") .. " dist=" .. math.floor(dist) .. "m depth=" .. math.floor(sub.depth) .. "m", false)

    if ASW_SOUND then
        ASW_SOUND:playForCoalition(self.ownerCoalition, "warning_sonar")
    end
end

function MADDetector:stopUpdateLoop()
    if self.updateScheduleId then
        timer.removeFunction(self.updateScheduleId)
        self.updateScheduleId = nil
    end
end

-- ===========================================================================
-- soundScheduler.lua
-- ===========================================================================

SoundScheduler = {}
SoundScheduler.__index = SoundScheduler

-- Priority levels (for reference, higher = more important)
SoundScheduler.PRIORITY = {
    LOW       = 1,   -- ambient loops (noise maker)
    NORMAL    = 2,   -- routine events (sonar ping, buoy deploy)
    HIGH      = 3,   -- tactical events (torpedo homing)
    CRITICAL  = 4,   -- launches (torpedo launch)
    ALERT     = 5,   -- warnings (torpedo in water)
}

-- Constructor
-- Creates a scheduler that manages sound playback per group,
-- preventing overlap and respecting priority.
function SoundScheduler:new()
    local obj = {
        sounds   = {},      -- name -> {file, duration, priority}
        channels = {},      -- groupName -> {currentSound, priority, endTime, scheduleId}
        loops    = {},      -- groupName -> {soundName -> {active, scheduleId}}
    }
    setmetatable(obj, SoundScheduler)
    return obj
end

-- Register a sound
-- name: unique identifier (e.g. "sonar_ping")
-- soundFile: filename inside the miz (e.g. "sonar_ping.ogg")
-- duration: length of the sound in seconds (must be known)
-- priority: number (use SoundScheduler.PRIORITY constants)
function SoundScheduler:register(name, soundFile, duration, priority)
    -- Use the provided soundFile path exactly as given. Caller is responsible
    -- for providing the correct path (e.g. "sounds/foo.ogg" or
    -- "l10n/DEFAULT/foo.ogg").
    self.sounds[name] = {
        file     = soundFile,
        duration = duration,
        priority = priority or SoundScheduler.PRIORITY.NORMAL,
    }
end

-- Play a sound once to a specific group
-- Returns true if the sound was played, false if blocked by higher priority
function SoundScheduler:playOnce(groupName, soundName)
    local sound = self.sounds[soundName]
    if not sound then return false end

    local dcsGroup = Group.getByName(groupName)
    if not dcsGroup or not dcsGroup:isExist() then return false end

    -- Debug log: record attempt to play sound for group
    env.info(string.format("SoundScheduler: playOnce request: group='%s' sound='%s' file='%s'", tostring(groupName), tostring(soundName), tostring(sound.file)), false)

    local now = timer.getTime()
    local ch = self.channels[groupName]

    -- Check if channel is busy
    if ch and ch.endTime > now then
        if sound.priority <= ch.priority then
            return false
        end
        -- Higher priority: interrupt current sound's end callback
        if ch.scheduleId then
            timer.removeFunction(ch.scheduleId)
        end
    end

    -- Play the sound
    trigger.action.outSoundForGroup(dcsGroup:getID(), sound.file)
    env.info(string.format("SoundScheduler: triggered outSoundForGroup id=%s file=%s", tostring(dcsGroup:getID()), tostring(sound.file)), false)

    -- Track when it ends
    local endTime = now + sound.duration
    local scheduleId = timer.scheduleFunction(function()
        local c = self.channels[groupName]
        if c and c.endTime <= timer.getTime() then
            c.currentSound = nil
            c.priority = 0
            c.scheduleId = nil
        end
    end, nil, endTime)

    self.channels[groupName] = {
        currentSound = soundName,
        priority     = sound.priority,
        endTime      = endTime,
        scheduleId   = scheduleId,
    }

    return true
end

-- Start looping a sound to a group
-- interval: seconds of silence between repeats (default 0 = back-to-back)
function SoundScheduler:startLoop(groupName, soundName, interval)
    local sound = self.sounds[soundName]
    if not sound then return end

    -- Stop any existing loop of the same sound
    self:stopLoop(groupName, soundName)

    if not self.loops[groupName] then
        self.loops[groupName] = {}
    end

    local loopState = { active = true, scheduleId = nil }
    self.loops[groupName][soundName] = loopState

    local function tick()
        if not loopState.active then return end

        local dcsGroup = Group.getByName(groupName)
        if not dcsGroup or not dcsGroup:isExist() then
            loopState.active = false
            return
        end

        local played = self:playOnce(groupName, soundName)

        -- If played, wait duration + interval before next play
        -- If blocked by higher priority, retry in 1 second
        local nextTime
        if played then
            nextTime = timer.getTime() + sound.duration + (interval or 0)
        else
            nextTime = timer.getTime() + 1
        end

        loopState.scheduleId = timer.scheduleFunction(function()
            tick()
        end, nil, nextTime)
    end

    tick()
end

-- Stop a specific loop for a group
function SoundScheduler:stopLoop(groupName, soundName)
    if not self.loops[groupName] then return end
    local loopState = self.loops[groupName][soundName]
    if not loopState then return end

    loopState.active = false
    if loopState.scheduleId then
        timer.removeFunction(loopState.scheduleId)
        loopState.scheduleId = nil
    end
    self.loops[groupName][soundName] = nil
end

-- Stop all sounds and loops for a group
function SoundScheduler:stopAll(groupName)
    -- Stop all loops
    if self.loops[groupName] then
        for soundName, _ in pairs(self.loops[groupName]) do
            self:stopLoop(groupName, soundName)
        end
        self.loops[groupName] = nil
    end

    -- Clear channel
    local ch = self.channels[groupName]
    if ch then
        if ch.scheduleId then
            timer.removeFunction(ch.scheduleId)
        end
        self.channels[groupName] = nil
    end
end

-- Check if a group currently has a sound playing
function SoundScheduler:isPlaying(groupName)
    local ch = self.channels[groupName]
    return ch ~= nil and ch.endTime > timer.getTime()
end

-- Check if a specific loop is active for a group
function SoundScheduler:isLooping(groupName, soundName)
    if not self.loops[groupName] then return false end
    local loopState = self.loops[groupName][soundName]
    return loopState ~= nil and loopState.active
end

-- Play a sound once to an entire coalition (fire-and-forget, no channel tracking)
-- coalitionId: coalition.side.RED, coalition.side.BLUE, or -1 for all
function SoundScheduler:playForCoalition(coalitionId, soundName)
    local sound = self.sounds[soundName]
    if not sound then return false end
    -- Debug log: record coalition playback
    env.info(string.format("SoundScheduler: playForCoalition request: coalition=%s sound='%s' file='%s'", tostring(coalitionId), tostring(soundName), tostring(sound.file)), false)
    trigger.action.outSoundForCoalition(coalitionId, sound.file)
    return true
end

-- ===========================================================================
-- ordnanceManager.lua
-- ===========================================================================

OrdnanceManager = {}
OrdnanceManager.__index = OrdnanceManager

local function debugMessage(message, duration)
    local dbg = trigger.misc.getUserFlag("Debug")
    if dbg == 1 then
        duration = duration or 10
        trigger.action.outText(message, duration, false)
        env.info(message, false)
    end
end

-- Base class for ASW hunter group management.
-- Handles buoy deployment, torpedo launch, inventory, rearm, and F10 menus.
-- Subclasses override initGroup() to add type-specific capabilities
-- (dipping sonar, buoy recovery, etc.).
--
-- config table:
--   ownerCoalition:   coalition side for ASW hunters
--   submarines:       table of detectable objects (VirtualSubmarine + NoiseMakers)
--   hunterPrefix:     group name prefix to find hunter groups
--   rearmZone:        trigger zone name for rearming (static fallback)
--   rearmUnits:       table of DCS unit names as moving rearm points (overrides rearmZone)
--   rearmRadius:      radius around each rearmUnit in meters (default 500)
--   maxBuoys:         max buoys per group (default 4)
--   maxTorpedoes:     max torpedoes per group (default 1)
--   maxAltitude:      max AGL in meters for deploy/launch operations (default 50)
--   maxSpeed:         max speed in m/s for deploy/launch operations (default 60)
--   recoveryRange:    max distance to recover a buoy in meters (default 10)
--   thermalLayerDepth thermal layer depth for spawned ordnance (default 90)
--   detectInterval:   seconds between sonarbuoy detection cycles (default 5)
--   buoys:            shared buoy pool table (default: new empty table)
--   torpedoes:        shared torpedo pool table (default: new empty table)
--   dippingSonars:    shared dipping sonar pool table (default: new empty table)
--   globalBuoyPool:   shared {count=N} table for mission-wide buoy reserve
--   buoyLifetime:     battery life in seconds per buoy (nil = unlimited)
function OrdnanceManager:new(config)
    local obj = {
        ownerCoalition    = config.ownerCoalition or coalition.side.BLUE,
        submarines        = config.submarines or {},
        hunterPrefix      = config.hunterPrefix or "_asw_hunter",
        rearmZone         = config.rearmZone or "ASW_Hunter_Rearming",
        rearmUnits        = config.rearmUnits or {},
        rearmRadius       = config.rearmRadius or 500,
        maxBuoys          = config.maxBuoys or 4,
        maxTorpedoes      = config.maxTorpedoes or 1,
        maxAltitude       = config.maxAltitude or 50,
        maxSpeed          = config.maxSpeed or 60,
        recoveryRange     = config.recoveryRange or 10,
        thermalLayerDepth = config.thermalLayerDepth or 90,
        detectInterval    = config.detectInterval or 5,
        buoys             = config.buoys or {},
        torpedoes         = config.torpedoes or {},
        dippingSonars     = config.dippingSonars or {},
        maxDepthCharges   = config.maxDepthCharges or 0,
        dcMaxAltitude     = config.dcMaxAltitude or 500,
        dcMaxSpeed        = config.dcMaxSpeed or 200,
        globalBuoyPool    = config.globalBuoyPool or {count = 0},
        buoyLifetime      = config.buoyLifetime,  -- nil = unlimited
        groupData         = {},
        buoyIdCounter     = 0,
        torpedoIdCounter  = 0,
        dcIdCounter       = 0,
        trackedGroups     = {},
    }
    setmetatable(obj, self)
    obj:startGroupScanner()
    return obj
end

function OrdnanceManager:startGroupScanner()
    -- In multiplayer, players join slots after the mission starts.
    -- React immediately when a player enters a hunter group slot so their
    -- menus are created right at join time (avoids F10 menu sync issues).
    local mgr = self
    local playerEnterHandler = {}
    function playerEnterHandler:onEvent(event)
        if event.id == world.event.S_EVENT_PLAYER_ENTER_UNIT then
            local unit = event.initiator
            if unit and unit:isExist() then
                local group = unit:getGroup()
                if group then
                    local gName = group:getName()
                    if mgr:isHunterGroup(gName) then
                        if not mgr.trackedGroups[gName] then
                            mgr:initGroup(gName)
                        elseif mgr.groupData[gName] then
                            -- Slot taken over from a previous player — show current inventory
                            mgr:showStatus(gName)
                        end
                    end
                end
            end
        end
    end
    world.addEventHandler(playerEnterHandler)

    local function scan()
        local allGroups = coalition.getGroups(self.ownerCoalition)
        if allGroups then
            for _, dcsGroup in ipairs(allGroups) do
                if dcsGroup and dcsGroup:isExist() then
                    local groupName = dcsGroup:getName()
                    if self:isHunterGroup(groupName) and not self.trackedGroups[groupName] then
                        self:initGroup(groupName)
                    end
                end
            end
        end
        self:cleanupDestroyedGroups()
        timer.scheduleFunction(function() scan() end, nil, timer.getTime() + 10)
    end
    scan()
end

function OrdnanceManager:cleanupDestroyedGroups()
    local toRemove = {}
    for groupName, _ in pairs(self.trackedGroups) do
        local dcsGroup = Group.getByName(groupName)
        if not dcsGroup or not dcsGroup:isExist() then
            toRemove[#toRemove + 1] = groupName
        end
    end

    for _, groupName in ipairs(toRemove) do
        local data = self.groupData[groupName]
        if data and data.dippingSonar then
            if data.dippingSonar:isDeployed() then
                data.dippingSonar:breakCable("Aircraft destroyed!")
            end
            data.dippingSonar:stopUpdateLoop()
            for i, sonar in ipairs(self.dippingSonars) do
                if sonar == data.dippingSonar then
                    table.remove(self.dippingSonars, i)
                    break
                end
            end
        end
        if data and data.madDetector then
            data.madDetector:stopUpdateLoop()
        end
        self.groupData[groupName] = nil
        self.trackedGroups[groupName] = nil
        debugMessage("ASW Hunter group destroyed, cleaned up: " .. groupName)
    end
end

function OrdnanceManager:isHunterGroup(groupName)
    return string.find(groupName, self.hunterPrefix, 1, true) ~= nil
end

-- Initialize tracking and menus for a hunter group.
-- Builds buoy deploy + torpedo + general menus, and stores handles in
-- data.menus so subclasses can extend them after calling this.
function OrdnanceManager:initGroup(groupName)
    if self.trackedGroups[groupName] then
        return
    end

    local dcsGroup = Group.getByName(groupName)
    if dcsGroup then
        local units = dcsGroup:getUnits()
        if units and #units > 1 then
            self.trackedGroups[groupName] = true
            self:log("ASW: Group '" .. groupName .. "' has " .. #units .. " units. Hunter groups must have exactly 1 unit — skipping.")
            return
        end
    end

    self.groupData[groupName] = {
        freshCount        = self.maxBuoys,
        savedBuoys        = {},
        expiredCount      = 0,
        torpedoInventory  = self.maxTorpedoes,
        torpedoDepth      = 100,
        dcInventory       = self.maxDepthCharges,
        dcDepth           = 50,
        dcCount           = 4,
        dcSpacing         = 200,
        state             = "idle",
        prepareScheduleId = nil,
        menus             = {},
    }

    local mooseGroup = GROUP:FindByName(groupName)
    if not mooseGroup then
        self.groupData[groupName] = nil  -- clean up so the next scan cycle can retry
        return
    end

    self.trackedGroups[groupName] = true
    local data = self.groupData[groupName]
    local rootMenu = MENU_GROUP:New(mooseGroup, "ASW Operations")
    data.menus.root = rootMenu

    -- Sonarbuoy submenu
    local buoyMenu = MENU_GROUP:New(mooseGroup, "Sonarbuoys", rootMenu)
    data.menus.buoy = buoyMenu
    MENU_GROUP_COMMAND:New(mooseGroup, "Prepare to Launch Buoy", buoyMenu, self.prepareToLaunch, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Launch Buoy!", buoyMenu, self.launchBuoy, self, groupName)

    -- Torpedo submenu
    local torpedoMenu = MENU_GROUP:New(mooseGroup, "Torpedo", rootMenu)
    data.menus.torpedo = torpedoMenu
    local depthMenu = MENU_GROUP:New(mooseGroup, "Set Search Depth", torpedoMenu)
    for _, d in ipairs({0, 50, 100, 150, 200, 250, 300, 400, 500}) do
        MENU_GROUP_COMMAND:New(mooseGroup, d .. "m", depthMenu, self.setTorpedoDepth, self, groupName, d)
    end
    MENU_GROUP_COMMAND:New(mooseGroup, "Prepare to Launch Torpedo", torpedoMenu, self.prepareToLaunchTorpedo, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Launch Torpedo!", torpedoMenu, self.launchTorpedo, self, groupName)

    -- Depth charges submenu (only shown when inventory is configured)
    if self.maxDepthCharges > 0 then
        local dcMenu = MENU_GROUP:New(mooseGroup, "Depth Charges", rootMenu)
        data.menus.dc = dcMenu
        local dcDepthMenu = MENU_GROUP:New(mooseGroup, "Set Detonation Depth", dcMenu)
        for _, d in ipairs({25, 50, 100, 150, 200, 300}) do
            MENU_GROUP_COMMAND:New(mooseGroup, d .. "m", dcDepthMenu, self.setDCDepth, self, groupName, d)
        end
        local dcCountMenu = MENU_GROUP:New(mooseGroup, "Set Count", dcMenu)
        for _, c in ipairs({1, 2, 4, 6, 8}) do
            MENU_GROUP_COMMAND:New(mooseGroup, c .. " charge(s)", dcCountMenu, self.setDCCount, self, groupName, c)
        end
        local dcSpacingMenu = MENU_GROUP:New(mooseGroup, "Set Spacing", dcMenu)
        for _, s in ipairs({100, 200, 400, 600}) do
            MENU_GROUP_COMMAND:New(mooseGroup, s .. "m", dcSpacingMenu, self.setDCSpacing, self, groupName, s)
        end
        MENU_GROUP_COMMAND:New(mooseGroup, "Prepare to Drop", dcMenu, self.prepareToDrop, self, groupName)
        MENU_GROUP_COMMAND:New(mooseGroup, "Drop!", dcMenu, self.dropCharges, self, groupName)
    end

    -- General
    MENU_GROUP_COMMAND:New(mooseGroup, "Cancel", rootMenu, self.cancelPrepare, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Status", rootMenu, self.showStatus, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Rearm", rootMenu, self.rearmAll, self, groupName)

    local unit = self:getGroupUnit(groupName)
    local typeName = unit and unit:getTypeName() or groupName
    self:messageToGroup(groupName, "ASW hunter slot active: " .. typeName .. "\nUse F10 \226\134\146 ASW Operations to begin.", 15)

    debugMessage("ASW Hunter group registered: " .. groupName)
end

function OrdnanceManager:getGroupUnit(groupName)
    local dcsGroup = Group.getByName(groupName)
    if not dcsGroup or not dcsGroup:isExist() then return nil end
    local units = dcsGroup:getUnits()
    if units and #units > 0 and units[1]:isExist() then
        return units[1]
    end
    return nil
end

function OrdnanceManager:getUnitHeading(unit)
    if not unit then return 0 end
    local pos = unit:getPosition()
    local hdg = math.deg(math.atan2(pos.x.z, pos.x.x))
    if hdg < 0 then hdg = hdg + 360 end
    return hdg
end

function OrdnanceManager:checkFlightParams(unit)
    if not unit then return false, "No aircraft found" end

    local pos = unit:getPoint()
    local landHeight = land.getHeight({x = pos.x, y = pos.z})
    local altitudeAGL = pos.y - landHeight
    local velocity = unit:getVelocity()
    local speed = math.sqrt(velocity.x^2 + velocity.y^2 + velocity.z^2)

    local altOk = altitudeAGL <= self.maxAltitude
    local spdOk = speed <= self.maxSpeed
    local speedKt = speed * 1.943844

    local msg = string.format("Alt: %.0fm AGL %s | Speed: %.0f kt %s",
        altitudeAGL, altOk and "OK" or "TOO HIGH",
        speedKt, spdOk and "OK" or "TOO FAST")

    return altOk and spdOk, msg
end

function OrdnanceManager:isPositionOverWater(x, z)
    local _, waterDepth = land.getSurfaceHeightWithSeabed({x = x, y = z})
    return waterDepth > 0
end

-- ===== SONARBUOY =====

function OrdnanceManager:prepareToLaunch(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "idle" then
        self:messageToGroup(groupName, "Cancel current operation first!", 5)
        return
    end

    local deployable = data.freshCount + #data.savedBuoys
    if deployable <= 0 then
        local hint = data.expiredCount > 0
            and string.format(" (%d expired buoys on board — rearm to revive)", data.expiredCount)
            or ""
        self:messageToGroup(groupName, "No buoys remaining! Return to rearm zone." .. hint, 5)
        return
    end

    data.state = "preparing_launch"
    local maxSpeedKt = self.maxSpeed * 1.943844

    local buoyInfo
    if #data.savedBuoys > 0 then
        local saved = data.savedBuoys[#data.savedBuoys]
        buoyInfo = "saved buoy (" .. saved:getBatteryText() .. " remaining)"
    elseif self.buoyLifetime then
        buoyInfo = string.format("fresh buoy (%d min battery)", math.floor(self.buoyLifetime / 60))
    else
        buoyInfo = "fresh buoy"
    end

    self:messageToGroup(groupName, string.format(
        "Preparing to launch buoy. Get into position.\nNext: %s\nAlt < %dm AGL | Speed < %.0f kt",
        buoyInfo, self.maxAltitude, maxSpeedKt), 5)
    self:startPrepareMessages(groupName)
end

function OrdnanceManager:launchBuoy(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "preparing_launch" then
        self:messageToGroup(groupName, "Use 'Prepare to Launch' first!", 5)
        return
    end

    local unit = self:getGroupUnit(groupName)
    local paramsOk, msg = self:checkFlightParams(unit)

    if not paramsOk then
        self:messageToGroup(groupName, "Cannot launch! " .. msg, 5)
        return
    end

    local pos = unit:getPoint()
    if not self:isPositionOverWater(pos.x, pos.z) then
        self:messageToGroup(groupName, "Cannot launch! You are over land, buoys must be deployed over water!", 5)
        return
    end

    local buoy
    if #data.savedBuoys > 0 then
        -- Redeploy a recovered buoy with its preserved battery
        local savedBuoy = table.remove(data.savedBuoys, #data.savedBuoys)
        local ok, err = savedBuoy:redeploy(pos.x, pos.z)
        if not ok then
            table.insert(data.savedBuoys, savedBuoy)
            self:messageToGroup(groupName, "Cannot deploy: " .. (err or "unknown error"), 5)
            self:stopPrepareMessages(groupName)
            data.state = "idle"
            return
        end
        buoy = savedBuoy
        self.buoys[#self.buoys + 1] = buoy
    else
        -- Deploy a fresh buoy (draws from freshCount)
        self.buoyIdCounter = self.buoyIdCounter + 1
        local buoyName = groupName .. "-Buoy-" .. self.buoyIdCounter
        buoy = Sonarbuoy:new(buoyName, pos.x, pos.z, self.ownerCoalition, nil, self.thermalLayerDepth, self.buoyLifetime)
        if not buoy then
            self:stopPrepareMessages(groupName)
            data.state = "idle"
            return
        end
        self.buoys[#self.buoys + 1] = buoy
        data.freshCount = data.freshCount - 1
    end

    local deployable = data.freshCount + #data.savedBuoys
    self:messageToGroup(groupName, string.format(
        "Buoy deployed! Ready: %d (%d fresh, %d saved) | Expired: %d | Pool: %d",
        deployable, data.freshCount, #data.savedBuoys, data.expiredCount, self.globalBuoyPool.count), 5)

    if ASW_SOUND then
        local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
        ASW_SOUND:playOnce(groupName, "buoy_splash")
        ASW_SOUND:playForCoalition(self.ownerCoalition, "buoy_splash")
        ASW_SOUND:playForCoalition(enemyCoalition, "buoy_splash")
    end

    self:stopPrepareMessages(groupName)
    data.state = "idle"
end

-- ===== TORPEDO =====

function OrdnanceManager:setTorpedoDepth(groupName, depth)
    local data = self.groupData[groupName]
    if not data then return end
    data.torpedoDepth = depth
    self:messageToGroup(groupName, "Torpedo search depth set to " .. depth .. "m", 5)
end

function OrdnanceManager:prepareToLaunchTorpedo(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "idle" then
        self:messageToGroup(groupName, "Cancel current operation first!", 5)
        return
    end

    if data.torpedoInventory <= 0 then
        self:messageToGroup(groupName, "No torpedoes remaining! Return to rearm.", 5)
        return
    end

    data.state = "preparing_torpedo"
    local maxSpeedKt = self.maxSpeed * 1.943844
    self:messageToGroup(groupName, "Preparing to launch torpedo.\nSearch depth: " .. data.torpedoDepth .. "m\nAlt < " .. self.maxAltitude .. "m AGL | Speed < " .. string.format("%.0f", maxSpeedKt) .. " kt\nTorpedo will follow your current heading.", 5)
    self:startPrepareMessages(groupName)
end

function OrdnanceManager:launchTorpedo(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "preparing_torpedo" then
        self:messageToGroup(groupName, "Use 'Prepare to Launch Torpedo' first!", 5)
        return
    end

    local unit = self:getGroupUnit(groupName)
    local paramsOk, msg = self:checkFlightParams(unit)

    if not paramsOk then
        self:messageToGroup(groupName, "Cannot launch torpedo! " .. msg, 5)
        return
    end

    self.torpedoIdCounter = self.torpedoIdCounter + 1
    local torpedoName = groupName .. "-Torpedo-" .. self.torpedoIdCounter
    local pos = unit:getPoint()
    local heading = self:getUnitHeading(unit)

    local torpedo = AntiSubmarineTorpedo:new(
        torpedoName, pos.x, pos.z, heading, data.torpedoDepth,
        self.ownerCoalition, self.submarines, self.thermalLayerDepth
    )

    if torpedo then
        self.torpedoes[#self.torpedoes + 1] = torpedo
        data.torpedoInventory = data.torpedoInventory - 1
        self:messageToGroup(groupName, string.format(
            "Torpedo away! Heading: %.0f° | Depth: %dm | Torpedoes remaining: %d/%d",
            heading, data.torpedoDepth, data.torpedoInventory, self.maxTorpedoes), 5)

        if ASW_SOUND then
            local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
            ASW_SOUND:playOnce(groupName, "torpedo_launch")
            ASW_SOUND:playForCoalition(self.ownerCoalition, "torpedo_launch")
            ASW_SOUND:playForCoalition(enemyCoalition, "warning_torpedo")
        end
    end

    self:stopPrepareMessages(groupName)
    data.state = "idle"
end

-- ===== GENERAL =====

function OrdnanceManager:cancelPrepare(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state == "idle" then
        self:messageToGroup(groupName, "Nothing to cancel.", 5)
        return
    end

    self:stopPrepareMessages(groupName)
    data.state = "idle"
    self:messageToGroup(groupName, "Operation cancelled.", 5)
end

function OrdnanceManager:showStatus(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    local deployedActive = 0
    local deployedDead   = 0
    for _, buoy in ipairs(self.buoys) do
        if buoy.active then
            if buoy.batteryDepleted then deployedDead   = deployedDead   + 1
            else                         deployedActive = deployedActive + 1
            end
        end
    end

    local activeTorpedoes = 0
    for _, torpedo in ipairs(self.torpedoes) do
        if torpedo:isActive() then activeTorpedoes = activeTorpedoes + 1 end
    end

    local deployable = data.freshCount + #data.savedBuoys
    local msg = string.format(
        "=== ASW Status ===\n" ..
        "Buoys: %d ready (%d fresh, %d saved) | %d expired | Pool: %d\n" ..
        "Deployed: %d active, %d dead\n" ..
        "Torpedoes: %d/%d | Active: %d | Depth: %dm\n" ..
        "State: %s",
        deployable, data.freshCount, #data.savedBuoys, data.expiredCount, self.globalBuoyPool.count,
        deployedActive, deployedDead,
        data.torpedoInventory, self.maxTorpedoes, activeTorpedoes,
        data.torpedoDepth, data.state)

    if data.dippingSonar then
        msg = msg .. "\nDipping sonar: " .. (data.dippingSonar.operational and data.dippingSonar.state or "BROKEN")
    end
    if data.dcInventory and self.maxDepthCharges > 0 then
        msg = msg .. string.format("\nDepth charges: %d/%d | Depth: %dm | %d x %dm",
            data.dcInventory, self.maxDepthCharges, data.dcDepth, data.dcCount, data.dcSpacing)
    end
    if data.madDetector then
        msg = msg .. "\n" .. data.madDetector:getStatusText()
    end

    self:messageToGroup(groupName, msg, 10)
end

function OrdnanceManager:rearmAll(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    local unit = self:getGroupUnit(groupName)
    if not unit then return end

    local pos = unit:getPoint()
    local inRange = false

    for _, unitName in ipairs(self.rearmUnits) do
        local rearmDcsUnit = Unit.getByName(unitName)
        if rearmDcsUnit and rearmDcsUnit:isExist() then
            local rPos = rearmDcsUnit:getPoint()
            local dx = pos.x - rPos.x
            local dz = pos.z - rPos.z
            if math.sqrt(dx * dx + dz * dz) <= self.rearmRadius then
                inRange = true
                break
            end
        end
    end

    if not inRange then
        local zone = trigger.misc.getZone(self.rearmZone)
        if zone then
            local dx = pos.x - zone.point.x
            local dz = pos.z - zone.point.z
            inRange = math.sqrt(dx * dx + dz * dz) <= zone.radius
        end
    end

    if not inRange then
        self:messageToGroup(groupName, "Not inside rearm zone! Fly to the designated rearm area.", 5)
        return
    end

    -- Revive expired recovered buoys (carrier replaces batteries — free)
    local revived = data.expiredCount
    data.freshCount  = data.freshCount + revived
    data.expiredCount = 0

    -- Top up from global pool up to maxBuoys
    local space    = self.maxBuoys - data.freshCount - #data.savedBuoys
    local fromPool = math.min(math.max(0, space), self.globalBuoyPool.count)
    if fromPool > 0 then
        data.freshCount              = data.freshCount + fromPool
        self.globalBuoyPool.count    = self.globalBuoyPool.count - fromPool
    end

    data.torpedoInventory = self.maxTorpedoes

    local extras = ""
    if data.dippingSonar and not data.dippingSonar.operational then
        data.dippingSonar:repair()
        extras = extras .. " | Sonar: REPAIRED"
    end
    if data.dcInventory ~= nil and self.maxDepthCharges > 0 then
        data.dcInventory = self.maxDepthCharges
        extras = extras .. " | DC: restocked"
    end
    if data.madDetector then
        data.madDetector.charge = 100
        extras = extras .. " | MAD: recharged"
    end

    local deployable = data.freshCount + #data.savedBuoys
    local poolNote   = self.globalBuoyPool.count == 0 and " (pool empty — recover buoys!)" or ""
    self:messageToGroup(groupName, string.format(
        "Rearmed!\nBuoys: %d ready (%d fresh, %d saved) | %d revived | Pool: %d%s\nTorpedoes: %d/%d%s",
        deployable, data.freshCount, #data.savedBuoys, revived, self.globalBuoyPool.count, poolNote,
        data.torpedoInventory, self.maxTorpedoes, extras), 8)
end

-- ===== PREPARE MODE HUD =====

function OrdnanceManager:startPrepareMessages(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    local function sendMessages()
        local d = self.groupData[groupName]
        if not d or d.state == "idle" then return end

        local unit = self:getGroupUnit(groupName)
        if not unit then return end

        local _, msg
        if d.state == "preparing_dc" then
            _, msg = self:checkDCFlightParams(unit)
        else
            _, msg = self:checkFlightParams(unit)
        end

        if d.state == "preparing_launch" then
            local pos = unit:getPoint()
            local overWater = self:isPositionOverWater(pos.x, pos.z)
            msg = msg .. "\n" .. (overWater and "WATER OK" or "LAND - NO DEPLOY")
        end

        if d.state == "preparing_recover" then
            local pos = unit:getPoint()
            local nearestDist  = nil
            local nearestName  = nil
            local nearestState = nil
            -- Show both powered and depleted buoys — both are recoverable
            for _, buoy in ipairs(self.buoys) do
                if buoy.active then
                    local dx   = buoy.x - pos.x
                    local dz   = buoy.z - pos.z
                    local dist = math.sqrt(dx * dx + dz * dz)
                    if not nearestDist or dist < nearestDist then
                        nearestDist  = dist
                        nearestName  = buoy.name
                        nearestState = buoy.batteryDepleted and "DEAD" or buoy:getBatteryText()
                    end
                end
            end
            if nearestDist then
                local rangeOk = nearestDist <= self.recoveryRange
                msg = msg .. string.format("\nNearest: %s [%s] (%.0fm) %s",
                    nearestName, nearestState, nearestDist, rangeOk and "IN RANGE" or "TOO FAR")
            else
                msg = msg .. "\nNo buoys deployed!"
            end
        end

        if d.state == "preparing_torpedo" then
            local heading = self:getUnitHeading(unit)
            msg = msg .. string.format("\nTorpedo heading: %.0f° | Search depth: %dm", heading, d.torpedoDepth)
        end

        if d.state == "preparing_dc" then
            local heading = self:getUnitHeading(unit)
            local pos = unit:getPoint()
            local overWater = self:isPositionOverWater(pos.x, pos.z)
            msg = msg .. string.format("\nHeading: %.0f° | Depth: %dm | %d charge(s) x %dm spacing",
                heading, d.dcDepth, d.dcCount, d.dcSpacing)
            msg = msg .. "\n" .. (overWater and "WATER OK" or "OVER LAND — charges will be discarded")
        end

        self:messageToGroup(groupName, msg, 1)

        data.prepareScheduleId = timer.scheduleFunction(function()
            sendMessages()
        end, nil, timer.getTime() + 1)
    end

    sendMessages()
end

function OrdnanceManager:stopPrepareMessages(groupName)
    local data = self.groupData[groupName]
    if data and data.prepareScheduleId then
        timer.removeFunction(data.prepareScheduleId)
        data.prepareScheduleId = nil
    end
end

-- ===== DEPTH CHARGES =====

function OrdnanceManager:checkDCFlightParams(unit)
    if not unit then return false, "No aircraft found" end
    local pos = unit:getPoint()
    local altitudeAGL = pos.y - land.getHeight({x = pos.x, y = pos.z})
    local velocity = unit:getVelocity()
    local speed = math.sqrt(velocity.x^2 + velocity.y^2 + velocity.z^2)
    local altOk = altitudeAGL <= self.dcMaxAltitude
    local spdOk = speed <= self.dcMaxSpeed
    local msg = string.format("Alt: %.0fm AGL %s | Speed: %.0f kt %s",
        altitudeAGL, altOk and "OK" or "TOO HIGH",
        speed * 1.943844, spdOk and "OK" or "TOO FAST")
    return altOk and spdOk, msg
end

function OrdnanceManager:setDCDepth(groupName, depth)
    local data = self.groupData[groupName]
    if not data then return end
    data.dcDepth = depth
    self:messageToGroup(groupName, "Depth charge detonation depth: " .. depth .. "m", 5)
end

function OrdnanceManager:setDCCount(groupName, count)
    local data = self.groupData[groupName]
    if not data then return end
    data.dcCount = count
    self:messageToGroup(groupName, "Depth charge count: " .. count, 5)
end

function OrdnanceManager:setDCSpacing(groupName, spacing)
    local data = self.groupData[groupName]
    if not data then return end
    data.dcSpacing = spacing
    self:messageToGroup(groupName, "Depth charge spacing: " .. spacing .. "m", 5)
end

function OrdnanceManager:prepareToDrop(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "idle" then
        self:messageToGroup(groupName, "Cancel current operation first!", 5)
        return
    end

    if data.dcInventory <= 0 then
        self:messageToGroup(groupName, "No depth charges remaining! Return to rearm.", 5)
        return
    end

    data.state = "preparing_dc"
    local maxSpeedKt = math.floor(self.dcMaxSpeed * 1.943844)
    self:messageToGroup(groupName, string.format(
        "Preparing depth charge drop.\nDepth: %dm | %d charge(s) x %dm spacing\nAlt < %dm AGL | Speed < %d kt",
        data.dcDepth, data.dcCount, data.dcSpacing, self.dcMaxAltitude, maxSpeedKt), 5)
    self:startPrepareMessages(groupName)
end

function OrdnanceManager:dropCharges(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "preparing_dc" then
        self:messageToGroup(groupName, "Use 'Prepare to Drop' first!", 5)
        return
    end

    local unit = self:getGroupUnit(groupName)
    local paramsOk, msg = self:checkDCFlightParams(unit)
    if not paramsOk then
        self:messageToGroup(groupName, "Cannot drop! " .. msg, 5)
        return
    end

    local count = math.min(data.dcCount, data.dcInventory)
    local pos = unit:getPoint()
    local heading = self:getUnitHeading(unit)
    local headingRad = math.rad(heading)
    local dirX = math.cos(headingRad)
    local dirZ = math.sin(headingRad)

    local dropped = 0
    local discarded = 0

    for i = 0, count - 1 do
        self.dcIdCounter = self.dcIdCounter + 1
        local charge = DepthCharge:new(
            groupName .. "-DC-" .. self.dcIdCounter,
            pos.x + dirX * i * data.dcSpacing,
            pos.z + dirZ * i * data.dcSpacing,
            data.dcDepth,
            self.ownerCoalition,
            self.submarines
        )
        if charge then dropped = dropped + 1 else discarded = discarded + 1 end
    end

    data.dcInventory = data.dcInventory - count

    local dropMsg = string.format(
        "Depth charges away! %d dropped | Depth: %dm | Spacing: %dm | Remaining: %d/%d",
        dropped, data.dcDepth, data.dcSpacing, data.dcInventory, self.maxDepthCharges)
    if discarded > 0 then
        dropMsg = dropMsg .. " | " .. discarded .. " discarded (over land)"
    end
    self:messageToGroup(groupName, dropMsg, 8)

    local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
    trigger.action.outTextForCoalition(enemyCoalition, "WARNING: Depth charges in the water!", 10, false)
    if ASW_SOUND then
        ASW_SOUND:playForCoalition(enemyCoalition, "warning_torpedo")
    end

    self:stopPrepareMessages(groupName)
    data.state = "idle"
end

-- ===== DETECTION LOOP =====
-- Call this once after creating all managers that share the same buoys table.

function OrdnanceManager:startDetectionLoop()
    local function detect()
        for _, buoy in ipairs(self.buoys) do
            buoy:tickBattery()
            if buoy:canDetect() then
                buoy:detect(self.submarines)
            end
        end
        timer.scheduleFunction(function() detect() end, nil, timer.getTime() + self.detectInterval)
    end
    timer.scheduleFunction(function() detect() end, nil, timer.getTime() + self.detectInterval)
end

-- ===== UTILITY =====

function OrdnanceManager:getDippingSonars()
    return self.dippingSonars
end

function OrdnanceManager:log(message)
    trigger.action.outTextForCoalition(self.ownerCoalition, message, 15, false)
    env.info(message, false)
end

function OrdnanceManager:messageToGroup(groupName, message, duration)
    local mooseGroup = GROUP:FindByName(groupName)
    if mooseGroup then
        trigger.action.outTextForGroup(mooseGroup:GetDCSObject():getID(), message, duration or 5, false)
    end
end

-- ===========================================================================
-- helicopterHunterManager.lua
-- ===========================================================================

HelicopterHunterManager = setmetatable({}, {__index = OrdnanceManager})
HelicopterHunterManager.__index = HelicopterHunterManager

-- Extends OrdnanceManager with helicopter-specific capabilities:
-- dipping sonar and buoy recovery. Uses the same low altitude/speed
-- limits as the base class defaults (50m AGL, 60 m/s).

function HelicopterHunterManager:initGroup(groupName)
    local unit = self:getGroupUnit(groupName)
    if unit and unit:getDesc().category ~= Unit.Category.HELICOPTER then
        self.trackedGroups[groupName] = true
        self:log("ASW WARNING: Group '" .. groupName .. "' has helicopter prefix but is not a helicopter — skipping.")
        return
    end

    OrdnanceManager.initGroup(self, groupName)

    local data = self.groupData[groupName]
    if not data then return end

    local mooseGroup = GROUP:FindByName(groupName)
    if not mooseGroup then return end

    -- Dipping sonar instance for this group
    data.dippingSonar = DippingSonar:new(groupName, self.ownerCoalition, self.thermalLayerDepth, self.submarines)
    self.dippingSonars[#self.dippingSonars + 1] = data.dippingSonar

    -- Add buoy recovery commands to the existing buoy menu
    MENU_GROUP_COMMAND:New(mooseGroup, "Prepare to Recover Buoy", data.menus.buoy, self.prepareToRecover, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Recover Buoy!", data.menus.buoy, self.recoverBuoy, self, groupName)

    -- Dipping sonar submenu
    local sonarMenu = MENU_GROUP:New(mooseGroup, "Dipping Sonar", data.menus.root)
    local extendMenu = MENU_GROUP:New(mooseGroup, "Extend Cable", sonarMenu)
    for _, d in ipairs({10, 25, 50, 100}) do
        MENU_GROUP_COMMAND:New(mooseGroup, "+" .. d .. "m", extendMenu, self.adjustSonarCable, self, groupName, d)
    end
    local retractMenu = MENU_GROUP:New(mooseGroup, "Retract Cable", sonarMenu)
    for _, d in ipairs({10, 25, 50, 100}) do
        MENU_GROUP_COMMAND:New(mooseGroup, "-" .. d .. "m", retractMenu, self.adjustSonarCable, self, groupName, -d)
    end
    MENU_GROUP_COMMAND:New(mooseGroup, "Lower Sonar", sonarMenu, self.lowerSonar, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Stop Sonar", sonarMenu, self.stopSonar, self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Raise Sonar", sonarMenu, self.raiseSonar, self, groupName)
end

-- ===== BUOY RECOVERY =====

function HelicopterHunterManager:prepareToRecover(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "idle" then
        self:messageToGroup(groupName, "Cancel current operation first!", 5)
        return
    end

    data.state = "preparing_recover"
    local maxSpeedKt = self.maxSpeed * 1.943844
    self:messageToGroup(groupName, "Preparing to recover buoy. Fly near a deployed buoy.\nAlt < " .. self.maxAltitude .. "m AGL | Speed < " .. string.format("%.0f", maxSpeedKt) .. " kt | Range < " .. self.recoveryRange .. "m\nBoth active and dead buoys can be recovered.", 5)
    self:startPrepareMessages(groupName)
end

function HelicopterHunterManager:recoverBuoy(groupName)
    local data = self.groupData[groupName]
    if not data then return end

    if data.state ~= "preparing_recover" then
        self:messageToGroup(groupName, "Use 'Prepare to Recover' first!", 5)
        return
    end

    local unit = self:getGroupUnit(groupName)
    local paramsOk, msg = self:checkFlightParams(unit)

    if not paramsOk then
        self:messageToGroup(groupName, "Cannot recover! " .. msg, 5)
        return
    end

    local pos = unit:getPoint()
    local nearestBuoy = nil
    local nearestDist = self.recoveryRange + 1
    local nearestIdx  = nil

    -- Scan all physically-deployed buoys (active OR depleted — both are on the water)
    for i, buoy in ipairs(self.buoys) do
        if buoy.active then
            local dx   = buoy.x - pos.x
            local dz   = buoy.z - pos.z
            local dist = math.sqrt(dx * dx + dz * dz)
            if dist < nearestDist then
                nearestDist = dist
                nearestBuoy = buoy
                nearestIdx  = i
            end
        end
    end

    if not nearestBuoy then
        self:messageToGroup(groupName, "No buoy within " .. self.recoveryRange .. "m range!", 5)
        return
    end

    -- Remove from the shared deployed pool
    table.remove(self.buoys, nearestIdx)

    local recoverMsg
    if nearestBuoy.batteryDepleted then
        -- Expired buoy: goes to expired inventory, revived at next rearm
        nearestBuoy:remove()
        data.expiredCount = data.expiredCount + 1
        recoverMsg = string.format(
            "%s recovered (battery dead — will be revived at rearm).\nExpired on board: %d | Ready: %d (%d fresh, %d saved)",
            nearestBuoy.name, data.expiredCount,
            data.freshCount + #data.savedBuoys, data.freshCount, #data.savedBuoys)
    else
        -- Active buoy: save with remaining battery, can be redeployed immediately
        nearestBuoy:pickup()
        data.savedBuoys[#data.savedBuoys + 1] = nearestBuoy
        recoverMsg = string.format(
            "%s recovered (%s battery saved).\nReady: %d (%d fresh, %d saved) | Expired: %d",
            nearestBuoy.name, nearestBuoy:getBatteryText(),
            data.freshCount + #data.savedBuoys, data.freshCount, #data.savedBuoys, data.expiredCount)
    end

    self:messageToGroup(groupName, recoverMsg, 8)

    if ASW_SOUND then
        local enemyCoalition = self.ownerCoalition == coalition.side.BLUE and coalition.side.RED or coalition.side.BLUE
        ASW_SOUND:playOnce(groupName, "recover_splash")
        ASW_SOUND:playForCoalition(self.ownerCoalition, "recover_splash")
        ASW_SOUND:playForCoalition(enemyCoalition, "recover_splash")
    end

    self:stopPrepareMessages(groupName)
    data.state = "idle"
end

-- ===== DIPPING SONAR =====

function HelicopterHunterManager:adjustSonarCable(groupName, delta)
    local data = self.groupData[groupName]
    if not data or not data.dippingSonar then return end
    local sonar = data.dippingSonar
    sonar:adjustCable(delta)
    local msg
    if sonar:isDeployed() then
        msg = string.format("Cable target: %dm (current: %.0fm) | Sonar depth: %.0fm",
            sonar.targetCableLength, sonar.currentCableLength, sonar:getWaterDepth())
    else
        msg = string.format("Cable target set to %dm (deploy with Lower Sonar)", sonar.targetCableLength)
    end
    self:messageToGroup(groupName, msg, 5)
end

function HelicopterHunterManager:lowerSonar(groupName)
    local data = self.groupData[groupName]
    if not data or not data.dippingSonar then return end
    local _, msg = data.dippingSonar:lower()
    self:messageToGroup(groupName, msg, 5)
end

function HelicopterHunterManager:stopSonar(groupName)
    local data = self.groupData[groupName]
    if not data or not data.dippingSonar then return end
    local _, msg = data.dippingSonar:stop()
    self:messageToGroup(groupName, msg, 5)
end

function HelicopterHunterManager:raiseSonar(groupName)
    local data = self.groupData[groupName]
    if not data or not data.dippingSonar then return end
    local _, msg = data.dippingSonar:raise()
    self:messageToGroup(groupName, msg, 5)
end

-- ===========================================================================
-- planeHunterManager.lua
-- ===========================================================================

PlaneHunterManager = setmetatable({}, {__index = OrdnanceManager})
PlaneHunterManager.__index = PlaneHunterManager

-- ASW fixed-wing hunter management.
-- Capabilities: sonarbuoy deployment, torpedo launch, MAD detector.
-- No dipping sonar. No buoy recovery.
-- Higher default altitude and speed limits than helicopters.

function PlaneHunterManager:new(config)
    config.maxAltitude = config.maxAltitude or 200
    config.maxSpeed    = config.maxSpeed    or 120
    local obj = OrdnanceManager.new(self, config)
    obj.madConfig = config.madConfig or {}
    return obj
end

function PlaneHunterManager:initGroup(groupName)
    local unit = self:getGroupUnit(groupName)
    if unit and unit:getDesc().category ~= Unit.Category.AIRPLANE then
        self.trackedGroups[groupName] = true
        self:log("ASW WARNING: Group '" .. groupName .. "' has fixed-wing prefix but is not a plane — skipping.")
        return
    end

    OrdnanceManager.initGroup(self, groupName)

    local data = self.groupData[groupName]
    if not data then return end

    local mooseGroup = GROUP:FindByName(groupName)
    if not mooseGroup then return end

    -- MAD Detector
    data.madDetector = MADDetector:new(groupName, self.ownerCoalition, self.submarines, self.madConfig)

    -- MAD submenu
    local madMenu = MENU_GROUP:New(mooseGroup, "MAD Detector", data.menus.root)
    MENU_GROUP_COMMAND:New(mooseGroup, "Activate MAD",   madMenu, self.activateMAD,   self, groupName)
    MENU_GROUP_COMMAND:New(mooseGroup, "Deactivate MAD", madMenu, self.deactivateMAD, self, groupName)
    local depthMenu = MENU_GROUP:New(mooseGroup, "Set Search Depth", madMenu)
    for _, d in ipairs({50, 100, 150, 200}) do
        MENU_GROUP_COMMAND:New(mooseGroup, d .. "m", depthMenu, self.setMADDepth, self, groupName, d)
    end
    MENU_GROUP_COMMAND:New(mooseGroup, "MAD Status", madMenu, self.showMADStatus, self, groupName)
end

-- ===== MAD ACTIONS =====

function PlaneHunterManager:activateMAD(groupName)
    local data = self.groupData[groupName]
    if not data or not data.madDetector then return end
    local _, msg = data.madDetector:activate()
    self:messageToGroup(groupName, msg, 8)
end

function PlaneHunterManager:deactivateMAD(groupName)
    local data = self.groupData[groupName]
    if not data or not data.madDetector then return end
    local _, msg = data.madDetector:deactivate()
    self:messageToGroup(groupName, msg, 8)
end

function PlaneHunterManager:setMADDepth(groupName, depth)
    local data = self.groupData[groupName]
    if not data or not data.madDetector then return end
    local msg = data.madDetector:setSearchDepth(depth)
    self:messageToGroup(groupName, msg, 5)
end

function PlaneHunterManager:showMADStatus(groupName)
    local data = self.groupData[groupName]
    if not data or not data.madDetector then return end
    local mad = data.madDetector
    local timeRemaining = mad.state == "active"
        and string.format(" | ~%.0fs remaining", mad.charge / mad:getDrainRate())
        or  string.format(" | ~%.0fs to full", (100 - mad.charge) / mad.rechargeRate)
    self:messageToGroup(groupName, mad:getStatusText() .. timeRemaining, 10)
end

-- ===========================================================================
-- humanSubmarineCommander.lua
-- ===========================================================================

HumanSubmarineCommander = {}
HumanSubmarineCommander.__index = HumanSubmarineCommander

-- Creates F10 coalition menus to control submarines
-- ownerCoalition: coalition.side.RED or coalition.side.BLUE
-- submarines: a table of VirtualSubmarine instances
function HumanSubmarineCommander:new(ownerCoalition, submarines, targetCoalition, buoys, detectableObjects)
    local obj = {
        ownerCoalition = ownerCoalition or coalition.side.RED,
        submarines = submarines or {},
        targetCoalition = targetCoalition or coalition.side.BLUE,
        buoys = buoys or {},
        detectableObjects = detectableObjects or {},  -- shared table that buoys scan
        torpedoes = {},
        torpedoIdCounter = 0,
        noiseMakers = {},
        noiseMakerIdCounter = 0
    }
    setmetatable(obj, HumanSubmarineCommander)
    obj:buildMenus()
    return obj
end

function HumanSubmarineCommander:buildMenus()
    local side = self.ownerCoalition
    local rootMenu = MENU_COALITION:New(side, "Submarine Command")

    for _, sub in ipairs(self.submarines) do
        local subMenu = MENU_COALITION:New(side, sub.name, rootMenu)

        -- Heading submenu
        local headingMenu = MENU_COALITION:New(side, "Change Heading", subMenu)
        local headingDeltas = {-90, -50, -25, -10, -5, 5, 10, 25, 50, 90}
        for _, delta in ipairs(headingDeltas) do
            local label = (delta > 0 and "+" or "") .. delta .. "°"
            MENU_COALITION_COMMAND:New(side, label, headingMenu, self.changeHeading, self, sub, delta)
        end

        -- Set Heading submenu
        local setHeadingMenu = MENU_COALITION:New(side, "Set Heading", subMenu)
        local headings = {
            {0, "N (000°)"}, {45, "NE (045°)"}, {90, "E (090°)"}, {135, "SE (135°)"},
            {180, "S (180°)"}, {225, "SW (225°)"}, {270, "W (270°)"}, {315, "NW (315°)"}
        }
        for _, h in ipairs(headings) do
            MENU_COALITION_COMMAND:New(side, h[2], setHeadingMenu, self.setHeading, self, sub, h[1])
        end

        -- Speed submenu
        local speedMenu = MENU_COALITION:New(side, "Change Speed", subMenu)
        local speedDeltas = {-10, -5, -2, -1, 1, 2, 5, 10}
        for _, delta in ipairs(speedDeltas) do
            local label = (delta > 0 and "+" or "") .. delta .. " m/s"
            MENU_COALITION_COMMAND:New(side, label, speedMenu, self.changeSpeed, self, sub, delta)
        end

        -- Depth submenu
        local depthMenu = MENU_COALITION:New(side, "Change Depth", subMenu)
        local depthDeltas = {-100, -50, -25, -10, 10, 25, 50, 100}
        for _, delta in ipairs(depthDeltas) do
            local label = (delta > 0 and "+" or "") .. delta .. "m"
            MENU_COALITION_COMMAND:New(side, label, depthMenu, self.changeDepth, self, sub, delta)
        end

        -- Quick depth commands
        MENU_COALITION_COMMAND:New(side, "Dive (max depth)", depthMenu, self.dive, self, sub)
        MENU_COALITION_COMMAND:New(side, "Periscope Depth", depthMenu, self.periscopeDepth, self, sub)
        MENU_COALITION_COMMAND:New(side, "Level (hold depth)", depthMenu, self.level, self, sub)

        -- Torpedo submenu
        local torpedoMenu = MENU_COALITION:New(side, "Torpedoes", subMenu)
        MENU_COALITION_COMMAND:New(side, "Fire Torpedo!", torpedoMenu, self.fireTorpedo, self, sub)
        MENU_COALITION_COMMAND:New(side, "Torpedo Status", torpedoMenu, self.torpedoStatus, self, sub)

        -- Noise Maker submenu
        local decoyMenu = MENU_COALITION:New(side, "Noise Makers", subMenu)
        local delayMenu = MENU_COALITION:New(side, "Deploy Noise Maker", decoyMenu)
        for _, delay in ipairs({0, 60, 120, 180, 240}) do
            local label = delay == 0 and "Immediate" or (delay .. "s delay")
            MENU_COALITION_COMMAND:New(side, label, delayMenu, self.deployNoiseMaker, self, sub, delay)
        end
        MENU_COALITION_COMMAND:New(side, "Noise Maker Status", decoyMenu, self.noiseMakerStatus, self, sub)
    end
end

function HumanSubmarineCommander:changeHeading(sub, delta)
    if not sub:isAlive() then return end
    local newHeading = (sub.targetHeading + delta) % 360
    sub:setCourse(newHeading)
end

function HumanSubmarineCommander:setHeading(sub, heading)
    if not sub:isAlive() then return end
    sub:setCourse(heading)
end

function HumanSubmarineCommander:changeSpeed(sub, delta)
    if not sub:isAlive() then return end
    local newSpeed = math.max(0, sub.targetSpeed + delta)
    sub:setSpeed(newSpeed)
end

function HumanSubmarineCommander:changeDepth(sub, delta)
    if not sub:isAlive() then return end
    local newDepth = math.max(0, sub.targetDepth + delta)
    sub:setTargetDepth(newDepth)
end

function HumanSubmarineCommander:dive(sub)
    if not sub:isAlive() then return end
    sub:setTargetDepth(sub.maxDepth)
end

function HumanSubmarineCommander:periscopeDepth(sub)
    if not sub:isAlive() then return end
    sub:setTargetDepth(20)
end

function HumanSubmarineCommander:level(sub)
    if not sub:isAlive() then return end
    sub:setTargetDepth(sub.depth)
end

function HumanSubmarineCommander:fireTorpedo(sub)
    if not sub:isAlive() then return end
    if sub.torpedoCount <= 0 then
        self:message(sub.name .. ": No torpedoes remaining!")
        return
    end
    if sub.depth > 30 then
        self:message(sub.name .. ": Must be at periscope depth (< 30m) to fire! Current depth: " .. string.format("%.0f", sub.depth) .. "m")
        return
    end

    sub.torpedoCount = sub.torpedoCount - 1
    self.torpedoIdCounter = self.torpedoIdCounter + 1
    local torpedoName = sub.name .. "-Torpedo-" .. self.torpedoIdCounter

    local torpedo = SubmarineTorpedo:new(
        torpedoName, sub.x, sub.z, sub.heading,
        self.ownerCoalition, self.targetCoalition, self.buoys
    )

    self.torpedoes[#self.torpedoes + 1] = torpedo
    self:message(sub.name .. ": Torpedo fired! Heading: " .. string.format("%.0f", sub.heading) .. "° | Remaining: " .. sub.torpedoCount .. "/" .. sub.maxTorpedoes)

    -- Torpedo launch sound for sub coalition + target coalition
    if ASW_SOUND then
        ASW_SOUND:playForCoalition(self.ownerCoalition, "torpedo_launch")
        ASW_SOUND:playForCoalition(self.targetCoalition, "torpedo_launch")
    end
end

function HumanSubmarineCommander:torpedoStatus(sub)
    local activeTorpedoes = 0
    for _, torp in ipairs(self.torpedoes) do
        if torp:isActive() then
            activeTorpedoes = activeTorpedoes + 1
        end
    end

    local depthOk = sub.depth <= 30
    local msg = string.format("%s Torpedo Status:\nRemaining: %d/%d\nActive in water: %d\nDepth: %.0fm %s",
        sub.name, sub.torpedoCount, sub.maxTorpedoes, activeTorpedoes,
        sub.depth, depthOk and "(READY)" or "(TOO DEEP - need < 30m)")
    self:message(msg, 10)
end

function HumanSubmarineCommander:message(msg, duration)
    duration = duration or 10
    trigger.action.outTextForCoalition(self.ownerCoalition, msg, duration, false)
end

-- ===== NOISE MAKERS =====

function HumanSubmarineCommander:deployNoiseMaker(sub, delay)
    if not sub:isAlive() then return end
    if sub.noiseMakerCount <= 0 then
        self:message(sub.name .. ": No noise makers remaining!")
        return
    end

    sub.noiseMakerCount = sub.noiseMakerCount - 1
    self.noiseMakerIdCounter = self.noiseMakerIdCounter + 1
    local decoyName = sub.name .. "-Decoy-" .. self.noiseMakerIdCounter

    local decoy = NoiseMaker:new(
        decoyName, sub.x, sub.z, sub.depth, delay,
        self.ownerCoalition, sub.thermalLayerDepth
    )

    self.noiseMakers[#self.noiseMakers + 1] = decoy
    -- Add to the shared detectable objects table so buoys will detect it
    self.detectableObjects[#self.detectableObjects + 1] = decoy

    self:message(string.format("%s: Noise maker deployed! Activates in %ds | Remaining: %d/%d",
        sub.name, delay, sub.noiseMakerCount, sub.maxNoiseMakers))
end

function HumanSubmarineCommander:noiseMakerStatus(sub)
    local activeCount = 0
    local standbyCount = 0
    for _, decoy in ipairs(self.noiseMakers) do
        if decoy:isDeployed() then
            if decoy:isAlive() then
                activeCount = activeCount + 1
            else
                standbyCount = standbyCount + 1
            end
        end
    end

    local msg = string.format("%s Noise Maker Status:\nRemaining: %d/%d\nStandby: %d | Active: %d",
        sub.name, sub.noiseMakerCount, sub.maxNoiseMakers, standbyCount, activeCount)
    self:message(msg, 10)
end

-- ===========================================================================
-- aiSubmarineCommander.lua
-- ===========================================================================

AISubmarineCommander = {}
AISubmarineCommander.__index = AISubmarineCommander

local function log(message, logCoalition, duration)
    duration = duration or 10
    trigger.action.outTextForCoalition(logCoalition, message, duration, false)
    env.info(message, false)
end

local function debugMessage(message, duration)
    if trigger.misc.getUserFlag("Debug") == 1 then
        duration = duration or 10
        trigger.action.outText(message, duration, false)
        env.info(message, false)
    end
end

-- Constructor
-- sub: VirtualSubmarine instance to command
-- config table:
--   waypointZones: table of trigger zone names for patrol route
--   patrolSpeed: speed in m/s while patrolling (default 5)
--   patrolDepth: depth in meters while patrolling (default 80)
--   attackRange: range to engage detected ships (default 12000)
--   evasionBuoyRange: distance to buoy that triggers evasion (default 7000)
--   evasionDuration: seconds to evade before resuming (default 180)
--   profile: "aggressive" or "cautious" (default "cautious")
--   targetCoalition: coalition whose ships to attack (default BLUE)
--   buoys: reference to buoys table for awareness
--   torpedoes: reference to ASW torpedoes table for awareness
--   detectableObjects: shared submarines table to insert noise makers into
local function nextAiMarkId()
    if not _aiSubMarkIdCounter then _aiSubMarkIdCounter = 400000 end
    _aiSubMarkIdCounter = _aiSubMarkIdCounter + 1
    return _aiSubMarkIdCounter
end

function AISubmarineCommander:new(sub, config)
    config = config or {}

    local profile = config.profile or "cautious"
    local isAggressive = profile == "aggressive"

    local obj = {
        sub = sub,
        waypointZones = config.waypointZones or {},
        patrolSpeed = config.patrolSpeed or 5,
        patrolDepth = config.patrolDepth or 80,
        attackRange = config.attackRange or (isAggressive and 15000 or 10000),
        evasionBuoyRange = config.evasionBuoyRange or 7000,
        evasionDuration = config.evasionDuration or (isAggressive and 120 or 240),
        profile = profile,
        targetCoalition = config.targetCoalition or coalition.side.BLUE,
        buoys = config.buoys or {},
        torpedoes = config.torpedoes or {},
        detectableObjects = config.detectableObjects or {},
        dippingSonars = config.dippingSonars or {},
        patrolMarks = {},

        -- Profile-specific settings
        attackSpeed = isAggressive and 8 or 4,
        attackTorpedoRange = isAggressive and 8000 or 5000,
        evasionSpeed = isAggressive and 3 or 1,
        silentChance = isAggressive and 0.3 or 0.7,  -- chance of going full stop during evasion

        randomPatrol = config.randomPatrol ~= false,
        enableAttack = config.enableAttack ~= false,

        -- State
        state = "patrol",      -- patrol, attack, evade
        currentWaypoint = nil,
        currentWaypointName = nil,
        waypointOrder = {},
        waypointIndex = 0,
        attackTarget = nil,
        torpedosFiredThisAttack = 0,
        evasionTimer = 0,
        lastUpdateTime = timer.getTime(),
        torpedoIdCounter = 0,
        noiseMakerIdCounter = 0,
        updateScheduleId = nil,
        aiStatusTextId = nil,
        planText = ""
    }
    setmetatable(obj, AISubmarineCommander)

    obj.aiStatusTextId = nextAiMarkId()
    obj:shuffleWaypoints()
    obj:nextWaypoint()
    obj:markPatrolPoints()
    obj:startPatrol()
    obj:startUpdateLoop()

    log("AI Commander (" .. profile .. ") active for " .. sub.name, sub.ownerCoalition)
    return obj
end

function AISubmarineCommander:shuffleWaypoints()
    local indices = {}
    for i = 1, #self.waypointZones do
        indices[#indices + 1] = i
    end
    if self.randomPatrol then
        -- Fisher-Yates shuffle
        for i = #indices, 2, -1 do
            local j = math.random(1, i)
            indices[i], indices[j] = indices[j], indices[i]
        end
    end
    self.waypointOrder = indices
    self.waypointIndex = 0
end

-- Advance to the next waypoint
function AISubmarineCommander:nextWaypoint()
    self.waypointIndex = self.waypointIndex + 1
    if self.waypointIndex > #self.waypointOrder then
        if self.randomPatrol then
            self:shuffleWaypoints()
        end
        self.waypointIndex = 1
    end

    local zoneIndex = self.waypointOrder[self.waypointIndex]
    local zoneName = self.waypointZones[zoneIndex]
    local zone = trigger.misc.getZone(zoneName)
    if zone then
        self.currentWaypoint = {x = zone.point.x, z = zone.point.z}
        self.currentWaypointName = zoneName
        debugMessage(self.sub.name .. " AI: heading to waypoint " .. zoneName)
    end
end

function AISubmarineCommander:markPatrolPoints()
    local coalitionId = self.sub.ownerCoalition or -1
    local green = {0, 1, 0, 1}

    for idx, zoneName in ipairs(self.waypointZones) do
        local zone = trigger.misc.getZone(zoneName)
        if zone then
            local point = {x = zone.point.x, y = 0, z = zone.point.z}
            local circleId = nextAiMarkId()
            trigger.action.circleToAll(coalitionId, circleId, point, 150, green, {0, 1, 0, 0.3}, 1, true)

            local textPoint = {x = zone.point.x + 200, y = 0, z = zone.point.z}
            local textId = nextAiMarkId()
            local label = "patrol point " .. zoneName
            trigger.action.textToAll(coalitionId, textId, textPoint, green, {0, 0, 0, 0}, 12, true, label)

            self.patrolMarks[#self.patrolMarks + 1] = {circleId = circleId, textId = textId}
        else
            debugMessage(self.sub.name .. " AI: patrol zone not found: " .. tostring(zoneName))
        end
    end
end

function AISubmarineCommander:updateStatusDisplay()
    if not self.aiStatusTextId then return end

    local coalitionId = self.sub.ownerCoalition or -1
    local textPoint = {x = self.sub.x + 200, y = 0, z = self.sub.z}
    local color = {0, 1, 0, 1}
    local bg = {0, 0, 0, 0.5}
    local status = "AI: " .. string.upper(self.state or "UNKNOWN")
    local plan = self.planText or ""

    if plan ~= "" then
        status = status .. " | " .. plan
    end

    trigger.action.textToAll(coalitionId, self.aiStatusTextId, textPoint, color, bg, 12, true, status)
end

-- Start patrol state
function AISubmarineCommander:startPatrol()
    self.state = "patrol"
    self.torpedosFiredThisAttack = 0
    self.planText = "Heading to " .. tostring(self.currentWaypointName or "next waypoint")
    self.sub:setSpeed(self.patrolSpeed)
    self.sub:setTargetDepth(self.patrolDepth)
    self:steerToWaypoint()
    self:updateStatusDisplay()
end

-- Steer toward current waypoint
function AISubmarineCommander:steerToWaypoint()
    if not self.currentWaypoint then return end
    local dx = self.currentWaypoint.x - self.sub.x
    local dz = self.currentWaypoint.z - self.sub.z
    local heading = math.deg(math.atan2(dz, dx))
    if heading < 0 then heading = heading + 360 end
    self.sub:setCourse(heading)
end

-- Main update loop: runs every 5 seconds
function AISubmarineCommander:startUpdateLoop()
    local function update()
        if not self.sub:isAlive() then return end

        local currentTime = timer.getTime()
        local dt = currentTime - self.lastUpdateTime
        self.lastUpdateTime = currentTime

        -- Always check for ASW torpedo threat (highest priority)
        if self.state ~= "evade" and self:detectASWTorpedo() then
            self:startTorpedoEvasion()
        -- Check for active dipping sonar (high priority)
        elseif self.state == "patrol" and self:detectActiveDippingSonar() then
            self:startDippingSonarEvasion()
        -- Check for buoy proximity
        elseif self.state == "patrol" and self:detectNearbyBuoy() then
            self:startBuoyEvasion()
        end

        -- State machine
        if self.state == "patrol" then
            self:updatePatrol(dt)
        elseif self.state == "attack" then
            self:updateAttack(dt)
        elseif self.state == "evade" then
            self:updateEvade(dt)
        end

        self:updateStatusDisplay()

        self.updateScheduleId = timer.scheduleFunction(function()
            update()
        end, nil, timer.getTime() + 5)
    end

    -- Start after a short delay
    timer.scheduleFunction(function()
        update()
    end, nil, timer.getTime() + 5)
end

-- ===== PATROL STATE =====
function AISubmarineCommander:updatePatrol(dt)
    -- Check if we reached the waypoint (within 1km)
    if self.currentWaypoint then
        local dx = self.currentWaypoint.x - self.sub.x
        local dz = self.currentWaypoint.z - self.sub.z
        local dist = math.sqrt(dx * dx + dz * dz)
        if dist < 1000 then
            self:nextWaypoint()
            self:steerToWaypoint()
        end
    end

    -- Check for ship targets via passive sonar
    if self.enableAttack then
        local target = self:findBestTarget()
        if target then
            self:startAttack(target)
        end
    end
end

-- ===== ATTACK STATE =====
function AISubmarineCommander:startAttack(target)
    self.state = "attack"
    self.attackTarget = target
    self.torpedosFiredThisAttack = 0
    self.planText = "Engage " .. tostring(target.unitName)

    -- Turn toward target
    local dx = target.x - self.sub.x
    local dz = target.z - self.sub.z
    local heading = math.deg(math.atan2(dz, dx))
    if heading < 0 then heading = heading + 360 end
    self.sub:setCourse(heading)
    self.sub:setSpeed(self.attackSpeed)
    self.sub:setTargetDepth(20) -- periscope depth for torpedo launch

    self:updateStatusDisplay()
    log(self.sub.name .. " AI: Target detected! Moving to attack.", self.sub.ownerCoalition)
end

function AISubmarineCommander:updateAttack(dt)
    if not self.attackTarget then
        self:startPatrol()
        return
    end

    -- Re-check target still exists
    local unit = Unit.getByName(self.attackTarget.unitName)
    if not unit or not unit:isExist() then
        log(self.sub.name .. " AI: Target lost. Resuming patrol.", self.sub.ownerCoalition)
        self:abortAttackAndEvade()
        return
    end

    -- Update target position
    local pos = unit:getPoint()
    self.attackTarget.x = pos.x
    self.attackTarget.z = pos.z

    -- Steer toward target
    local dx = pos.x - self.sub.x
    local dz = pos.z - self.sub.z
    local dist = math.sqrt(dx * dx + dz * dz)
    local heading = math.deg(math.atan2(dz, dx))
    if heading < 0 then heading = heading + 360 end
    self.sub:setCourse(heading)

    -- Check if we can fire (at periscope depth and in range)
    if self.sub.depth <= 30 and dist <= self.attackTorpedoRange and self.torpedosFiredThisAttack < 2 then
        if self.sub.torpedoCount > 0 then
            self:fireTorpedo()
            self.torpedosFiredThisAttack = self.torpedosFiredThisAttack + 1

            -- After 2 torpedoes, dive and evade to random waypoint
            if self.torpedosFiredThisAttack >= 2 then
                self:abortAttackAndEvade()
            end
        else
            -- No torpedoes, abort
            log(self.sub.name .. " AI: No torpedoes remaining. Disengaging.", self.sub.ownerCoalition)
            self:abortAttackAndEvade()
        end
    end
end

function AISubmarineCommander:abortAttackAndEvade()
    self.attackTarget = nil
    self.state = "evade"
    self.evasionTimer = 0
    self.planText = "Disengage and dive deep"

    -- Dive deep, random heading toward a patrol point
    self.sub:setTargetDepth(self.sub.maxDepth)
    self.sub:setSpeed(self.evasionSpeed)
    self:nextWaypoint()
    self:steerToWaypoint()
    self:updateStatusDisplay()

    log(self.sub.name .. " AI: Disengaging. Diving deep.", self.sub.ownerCoalition)
end

-- ===== EVASION STATE =====

-- Evade because a buoy was detected nearby
function AISubmarineCommander:startBuoyEvasion()
    self.state = "evade"
    self.evasionTimer = 0
    self.attackTarget = nil
    self.planText = "Evade nearby buoy"

    -- Find the nearest buoy to flee from
    local nearestBuoy = self:findNearestBuoy()

    -- Dive deep, reduce speed
    self.sub:setTargetDepth(self.sub.maxDepth)
    self.sub:setSpeed(self.evasionSpeed)

    -- Head away from buoy in a 180° cone
    if nearestBuoy then
        local dx = self.sub.x - nearestBuoy.x
        local dz = self.sub.z - nearestBuoy.z
        local awayHeading = math.deg(math.atan2(dz, dx))
        if awayHeading < 0 then awayHeading = awayHeading + 360 end
        -- Add random offset ±90°
        local offset = (math.random() * 180) - 90
        local finalHeading = (awayHeading + offset) % 360
        self.sub:setCourse(finalHeading)
    end

    self:updateStatusDisplay()
    log(self.sub.name .. " AI: Buoy detected nearby! Evading.", self.sub.ownerCoalition)
end

-- Evade because an ASW torpedo was detected
function AISubmarineCommander:startTorpedoEvasion()
    self.state = "evade"
    self.evasionTimer = 0
    self.attackTarget = nil
    self.planText = "Evade incoming ASW torpedo"

    -- Deploy noise maker immediately (no delay for torpedo distraction)
    if self.sub.noiseMakerCount > 0 then
        self:deployNoiseMaker(0)
    end

    -- Random depth change: either go deep or go shallow
    if math.random() > 0.5 then
        self.sub:setTargetDepth(self.sub.maxDepth)
    else
        self.sub:setTargetDepth(math.max(0, self.sub.depth - 100))
    end

    -- Go silent or very slow
    if math.random() < self.silentChance then
        self.sub:setSpeed(0)
    else
        self.sub:setSpeed(self.evasionSpeed)
    end

    -- Random heading
    self.sub:setCourse(math.random(0, 359))

    self:updateStatusDisplay()
    log(self.sub.name .. " AI: ASW TORPEDO DETECTED! Emergency evasion!", self.sub.ownerCoalition)
end

function AISubmarineCommander:updateEvade(dt)
    self.evasionTimer = self.evasionTimer + dt

    -- Check for ASW torpedo during evasion (may need to re-deploy noise maker)
    if self:detectASWTorpedo() then
        -- Reset evasion timer, deploy another noise maker if available
        self.evasionTimer = 0
        if self.sub.noiseMakerCount > 0 then
            self:deployNoiseMaker(60)
        end
        -- Change heading again
        self.sub:setCourse(math.random(0, 359))
    end

    if self.evasionTimer >= self.evasionDuration then
        log(self.sub.name .. " AI: Evasion complete. Resuming patrol.", self.sub.ownerCoalition)
        self:nextWaypoint()
        self:startPatrol()
    end
end

-- ===== THREAT DETECTION =====

-- Check if any active buoy is within evasion range
function AISubmarineCommander:detectNearbyBuoy()
    for _, buoy in ipairs(self.buoys) do
        if buoy:isActive() then
            local dx = buoy.x - self.sub.x
            local dz = buoy.z - self.sub.z
            local dist = math.sqrt(dx * dx + dz * dz)
            if dist < self.evasionBuoyRange then
                return true
            end
        end
    end
    return false
end

-- Find nearest buoy for evasion heading
function AISubmarineCommander:findNearestBuoy()
    local nearest = nil
    local nearestDist = math.huge
    for _, buoy in ipairs(self.buoys) do
        if buoy:isActive() then
            local dx = buoy.x - self.sub.x
            local dz = buoy.z - self.sub.z
            local dist = math.sqrt(dx * dx + dz * dz)
            if dist < nearestDist then
                nearestDist = dist
                nearest = buoy
            end
        end
    end
    return nearest
end

-- Check if any active ASW torpedo is within 10km
function AISubmarineCommander:detectASWTorpedo()
    for _, torpedo in ipairs(self.torpedoes) do
        if torpedo:isActive() then
            local dx = torpedo.x - self.sub.x
            local dz = torpedo.z - self.sub.z
            local dist = math.sqrt(dx * dx + dz * dz)
            if dist < 10000 then
                return true
            end
        end
    end
    return false
end

-- Check if any active dipping sonar is within 10km
function AISubmarineCommander:detectActiveDippingSonar()
    for _, sonar in ipairs(self.dippingSonars) do
        if sonar.state == "active" then
            local unit = sonar:getUnit()
            if unit then
                local pos = unit:getPoint()
                local dx = pos.x - self.sub.x
                local dz = pos.z - self.sub.z
                local dist = math.sqrt(dx * dx + dz * dz)
                if dist < 10000 then
                    return true, pos
                end
            end
        end
    end
    return false
end

-- Evade active dipping sonar: dive deep, move away, deploy noise maker
function AISubmarineCommander:startDippingSonarEvasion()
    self.state = "evade"
    self.evasionTimer = 0
    self.attackTarget = nil
    self.planText = "Evade active dipping sonar"

    -- Find nearest active dipping sonar
    local nearestDist = math.huge
    local nearestPos = nil
    for _, sonar in ipairs(self.dippingSonars) do
        if sonar.state == "active" then
            local unit = sonar:getUnit()
            if unit then
                local pos = unit:getPoint()
                local dx = pos.x - self.sub.x
                local dz = pos.z - self.sub.z
                local dist = math.sqrt(dx * dx + dz * dz)
                if dist < nearestDist then
                    nearestDist = dist
                    nearestPos = pos
                end
            end
        end
    end

    -- Dive deep, reduce speed
    self.sub:setTargetDepth(self.sub.maxDepth)
    self.sub:setSpeed(self.evasionSpeed)

    -- Head away from the dipping sonar helicopter
    if nearestPos then
        local dx = self.sub.x - nearestPos.x
        local dz = self.sub.z - nearestPos.z
        local awayHeading = math.deg(math.atan2(dz, dx))
        if awayHeading < 0 then awayHeading = awayHeading + 360 end
        local jitter = math.random(-90, 90)
        self.sub:setCourse((awayHeading + jitter) % 360)
    end

    -- Deploy noise maker with short delay to confuse active sonar
    if self.sub.noiseMakerCount > 0 then
        self:deployNoiseMaker(60) -- 60 second delay
    end

    self:updateStatusDisplay()
    log(self.sub.name .. " AI: Active sonar detected! Evading deep.", self.sub.ownerCoalition)
end

-- ===== TARGET ACQUISITION =====

-- Find best ship target using passive sonar
function AISubmarineCommander:findBestTarget()
    local enemyGroups = coalition.getGroups(self.targetCoalition, Group.Category.SHIP)
    if not enemyGroups then return nil end

    local bestTarget = nil
    local bestDist = self.attackRange + 1

    for _, group in ipairs(enemyGroups) do
        if group and group:isExist() then
            local units = group:getUnits()
            if units then
                for _, unit in ipairs(units) do
                    if unit and unit:isExist() then
                        local pos = unit:getPoint()
                        local dx = pos.x - self.sub.x
                        local dz = pos.z - self.sub.z
                        local dist = math.sqrt(dx * dx + dz * dz)

                        -- Must be within sonar range (considering thermal layer)
                        local effectiveRange = self.sub.sonarRange
                        if self.sub.belowThermalLayer then
                            effectiveRange = effectiveRange * self.sub.sonarThermalPenalty
                        end

                        if dist < effectiveRange and dist < self.attackRange and dist < bestDist then
                            bestDist = dist
                            bestTarget = {
                                x = pos.x,
                                z = pos.z,
                                unitName = unit:getName(),
                                distance = dist
                            }
                        end
                    end
                end
            end
        end
    end

    return bestTarget
end

-- ===== ACTIONS =====

function AISubmarineCommander:fireTorpedo()
    if self.sub.torpedoCount <= 0 then return end
    if self.sub.depth > 30 then return end

    self.sub.torpedoCount = self.sub.torpedoCount - 1
    self.torpedoIdCounter = self.torpedoIdCounter + 1
    local torpedoName = self.sub.name .. "-AI-Torpedo-" .. self.torpedoIdCounter

    local torpedo = SubmarineTorpedo:new(
        torpedoName, self.sub.x, self.sub.z, self.sub.heading,
        self.sub.ownerCoalition, self.targetCoalition, self.buoys
    )

    log(self.sub.name .. " AI: Torpedo fired! Remaining: " .. self.sub.torpedoCount .. "/" .. self.sub.maxTorpedoes, self.sub.ownerCoalition)
end

function AISubmarineCommander:deployNoiseMaker(delay)
    if self.sub.noiseMakerCount <= 0 then return end

    self.sub.noiseMakerCount = self.sub.noiseMakerCount - 1
    self.noiseMakerIdCounter = self.noiseMakerIdCounter + 1
    local decoyName = self.sub.name .. "-AI-Decoy-" .. self.noiseMakerIdCounter

    local decoy = NoiseMaker:new(
        decoyName, self.sub.x, self.sub.z, self.sub.depth, delay,
        self.sub.ownerCoalition, self.sub.thermalLayerDepth
    )

    -- Add to shared detectable objects so buoys will pick it up
    self.detectableObjects[#self.detectableObjects + 1] = decoy

    log(self.sub.name .. " AI: Noise maker deployed! Activates in " .. delay .. "s | Remaining: " .. self.sub.noiseMakerCount .. "/" .. self.sub.maxNoiseMakers, self.sub.ownerCoalition)
end
